import { computed, shallowRef, toValue, watchEffect, type ComponentPublicInstance, type MaybeRefOrGetter, type VNodeChild, type VNodeRef } from 'vue'
import type { Tier } from '@/lib/ink/types'
import { bucketBox, stableStringify, type Box, type InkLayerName, type Recipe } from '@/lib/ink/recipes'
import { inkFrame } from './cache'
import { useInkContext, useInkSeed } from './context'
import { ensureInkDefs } from './defs'
import { InkSvg } from './svg'

export type ElementRef = (element: Element | ComponentPublicInstance | null) => void
export interface UseInkOptions<P> {
  recipe: Recipe<P>
  params: P
  kind?: string
  pad?: number
  size?: readonly [number, number]
  tier?: Tier
  layers?: 'lazy' | 'all' | readonly InkLayerName[]
  seed?: string | number
  still?: boolean
}
export interface InkHostProps { 'data-ink-host': ''; 'data-ink-ready'?: '' }

// Reka UI 暴露的是组件实例；绘制必须测量实际宿主元素，而非组件代理。
export function toElement(value: Element | ComponentPublicInstance | null): HTMLElement | null {
  let element = value && '$el' in value ? value.$el as Node : value
  // Reka 的 Fragment 根节点以前导注释定位，实际宿主紧随其后。
  if (element && !(element instanceof Element)) element = element.nextSibling
  return element instanceof HTMLElement ? element : null
}
export function useInkBox(source: MaybeRefOrGetter<{ size?: readonly [number, number] }>) {
  const element = shallowRef<HTMLElement | null>(null)
  const box = shallowRef<Box | null>(null)
  watchEffect((cleanup) => {
    const explicit = toValue(source).size
    if (explicit) { box.value = bucketBox(explicit[0], explicit[1]); return }
    const el = element.value
    if (!el) return
    const update = () => {
      const w = el.offsetWidth
      const h = el.offsetHeight
      if (!(w > 0 && h > 0)) return
      const next = bucketBox(w, h)
      if (!box.value || box.value.w !== next.w || box.value.h !== next.h) box.value = next
    }
    update()
    const observer = new ResizeObserver(update)
    observer.observe(el)
    cleanup(() => observer.disconnect())
  }, { flush: 'post' })
  const hostRef: ElementRef = value => { element.value = toElement(value) }
  return { hostRef, element, box }
}

export function useInkCore<P>(source: MaybeRefOrGetter<UseInkOptions<P>>) {
  const options = computed(() => toValue(source))
  const context = useInkContext()
  const seed = useInkSeed(() => options.value.seed)
  const { hostRef, element, box } = useInkBox(() => ({ size: options.value.size }))
  const wanted = shallowRef<readonly InkLayerName[]>([])
  const seenDir = shallowRef<'ltr' | 'rtl'>()
  watchEffect(cleanup => {
    const el = element.value
    const recipe = options.value.recipe
    if (!el) return
    if (!context.value.hasProvider) ensureInkDefs()
    const direction = el.closest('[dir]')?.getAttribute('dir') ?? el.ownerDocument.documentElement.getAttribute('dir')
    seenDir.value = direction === 'ltr' || direction === 'rtl' ? direction : undefined
    const cleanups: Array<() => void> = []
    const triggers: Partial<Record<InkLayerName, string[]>> = { focus: ['focusin'], hover: ['pointerenter'], pressed: ['pointerdown', 'keydown'] }
    for (const layer of recipe.lazy) {
      for (const type of triggers[layer] ?? []) {
        const listener = (event: Event) => {
          if (layer === 'focus' && event.target instanceof Element && !event.target.matches(':focus-visible')) return
          if (event.type === 'keydown' && !['Enter', ' '].includes((event as KeyboardEvent).key)) return
          if (!wanted.value.includes(layer)) wanted.value = [...wanted.value, layer]
        }
        el.addEventListener(type, listener, { passive: true })
        cleanups.push(() => el.removeEventListener(type, listener))
      }
    }
    cleanup(() => cleanups.forEach(stop => stop()))
  }, { flush: 'post' })
  const frame = computed(() => {
    if (!box.value) return null
    const o = options.value
    const ctx = context.value
    const eager = o.layers === 'all' || (o.layers === undefined && (o.tier ?? ctx.tier) === 'hi') ? o.recipe.lazy : Array.isArray(o.layers) ? o.layers : []
    return inkFrame(o.recipe, { box: box.value, params: o.params, seed: seed.value, tier: o.tier ?? ctx.tier, density: ctx.density, dir: seenDir.value ?? ctx.dir, knobs: ctx.knobs, pad: o.pad, paramsKey: stableStringify(o.params), lazy: [...new Set([...eager, ...wanted.value])] })
  })
  const hostProps = computed<InkHostProps>(() => frame.value ? { 'data-ink-host': '', 'data-ink-ready': '' } : { 'data-ink-host': '' })
  const still = computed(() => options.value.still ?? (context.value.density === 'calm' || context.value.motion === 'reduced'))
  return { hostRef, hostProps, frame, box, seed, still }
}

export function useInk<P>(source: MaybeRefOrGetter<UseInkOptions<P>>) {
  const core = useInkCore(source)
  const node = computed<VNodeChild>(() => core.frame.value ? <InkSvg kind={toValue(source).kind ?? toValue(source).recipe.kind} frame={core.frame.value} still={core.still.value} /> : null)
  return { ...core, node }
}
export type UseInkResult = ReturnType<typeof useInk>

// 与 Vue 模板 ref 生命周期配合，同时转发绘制引用和使用者引用。
export function useMergedRef<T extends Element>(...refs: Array<VNodeRef | ((value: T | null) => unknown) | { value: T | null } | undefined>) {
  const stops = new Map<unknown, () => void>()
  return (value: Element | ComponentPublicInstance | null) => {
    for (const source of refs) {
      const element = toElement(value) as T | null
      if (typeof source === 'function') {
        stops.get(source)?.()
        stops.delete(source)
        const stop = (source as (element: T | null, refs: Record<string, unknown>) => unknown)(element, {})
        if (typeof stop === 'function') stops.set(source, stop as () => void)
      }
      else if (source && typeof source !== 'string') source.value = element
    }
  }
}
export const mergeRefs = (...refs: Array<ElementRef | undefined>): ElementRef => value => refs.forEach(ref => ref?.(value))

import { computed, inject, provide, defineComponent, type ComputedRef, type InjectionKey } from 'vue'

// 图标尺寸通过 Vue 注入传递，保持按钮各尺寸下的原版图标比例。
export const IconSizeContext: InjectionKey<ComputedRef<number | undefined>> = Symbol('LooseleafIconSize')
export function useIconSize() { return inject(IconSizeContext, computed(() => undefined)) }
export const IconSizeProvider = defineComponent({
  name: 'IconSizeProvider',
  props: { value: Number },
  setup(props, { slots }) {
    provide(IconSizeContext, computed(() => props.value))
    return () => slots.default?.()
  },
})

import { onBeforeUnmount, watch, type MaybeRefOrGetter } from 'vue'
import { defineUi } from '@/lib/component'
import { useInkCore, toElement, type UseInkOptions } from './hooks'
import { InkSvg } from './svg'

export type InkProps<P> = UseInkOptions<P>
// 独立 Ink 层测量其父元素，保持上游可嵌入任意原生 DOM 的使用方式。
export const Ink = defineUi<UseInkOptions<unknown>>('Ink', ['recipe', 'params', 'kind', 'pad', 'size', 'tier', 'layers', 'seed', 'still'], props => {
  const core = useInkCore(props as MaybeRefOrGetter<UseInkOptions<unknown>>)
  let host: HTMLElement | null = null
  const anchor = (element: Parameters<typeof toElement>[0]) => {
    host = toElement(element)?.parentElement ?? null
    if (host) { host.setAttribute('data-ink-host', ''); core.hostRef(host) }
  }
  watch(core.frame, frame => { if (host) { if (frame) host.setAttribute('data-ink-ready', ''); else host.removeAttribute('data-ink-ready') } })
  onBeforeUnmount(() => { host?.removeAttribute('data-ink-host'); host?.removeAttribute('data-ink-ready') })
  return () => <InkSvg ref={anchor} kind={props.kind ?? props.recipe.kind} frame={core.frame.value} still={core.still.value} />
})

import { computed, onBeforeUnmount, onMounted, provide, shallowRef, watch } from 'vue'
import { defineUi } from '@/lib/component'
import type { Knobs } from '@/lib/ink/builder'
import type { Tier } from '@/lib/ink/types'
import type { PaperTileName } from '@/lib/ink/textures'
import { DEFAULT_KNOBS, resolveKnobs, type Density, type Dir } from '@/lib/ink/recipes'
import { InkContext, useInkContext, type InkScopeProps } from './context'
import { InkDefs, InkTiles } from './defs'

export interface InkProviderProps {
  tier?: Tier
  density?: Density
  motion?: 'system' | 'reduced'
  theme?: string
  dir?: Dir
  knobs?: Partial<Knobs>
  textures?: boolean | readonly PaperTileName[]
  defs?: boolean
  patterns?: boolean | readonly PaperTileName[]
}

export const InkProvider = defineUi<InkProviderProps>('InkProvider', ['tier', 'density', 'motion', 'theme', 'dir', 'knobs', 'textures', 'defs', 'patterns'], (props, { slots }) => {
  const outer = useInkContext()
  const element = shallowRef<HTMLElement>()
  const cssKnobs = shallowRef<Knobs>(DEFAULT_KNOBS)
  const inheritedDensity = shallowRef<Density>('comfortable')
  const inheritedDir = shallowRef<Dir>('ltr')
  const read = () => {
    const el = element.value
    if (!el) return
    const css = getComputedStyle(el)
    // 读取上游定义的 CSS token，保持 CSS 调参和绘制算法同步。
    const token = (name: string, initial: number) => { const value = Number.parseFloat(css.getPropertyValue(name)); return Number.isFinite(value) ? value : initial }
    cssKnobs.value = { wobble: token('--ll-wobble', 1), misreg: token('--ll-misreg-k', 1), bleed: token('--ll-bleed', 6) / 6, width: token('--ll-stroke-fine', 1.7) / 1.7 }
    const density = el.parentElement?.closest('[data-density]')?.getAttribute('data-density')
    inheritedDensity.value = density === 'compact' || density === 'calm' ? density : 'comfortable'
    const dir = el.parentElement?.closest('[dir]')?.getAttribute('dir') ?? el.ownerDocument.documentElement.getAttribute('dir')
    inheritedDir.value = dir === 'rtl' ? 'rtl' : 'ltr'
  }
  let observer: MutationObserver | undefined
  onMounted(() => {
    read()
    observer = new MutationObserver(read)
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme', 'data-density', 'data-motion', 'dir'] })
    if (element.value) observer.observe(element.value, { attributes: true, attributeFilter: ['data-theme', 'data-density', 'data-motion', 'dir'] })
  })
  onBeforeUnmount(() => observer?.disconnect())
  watch(() => [props.theme, props.density, props.motion], read, { flush: 'post' })
  const value = computed(() => {
    const density = props.density ?? inheritedDensity.value
    const scope: InkScopeProps = { ...outer.value.scope }
    if (props.density) scope['data-density'] = props.density
    if (props.motion === 'reduced') scope['data-motion'] = 'reduced'
    if (props.theme) scope['data-theme'] = props.theme
    return { tier: props.tier ?? 'lo', density, dir: props.dir ?? inheritedDir.value, motion: props.motion ?? 'system', knobs: resolveKnobs({ ...cssKnobs.value, ...props.knobs }, density), hasProvider: true, scope }
  })
  provide(InkContext.key, value)
  return () => <div ref={element} data-ll-scope="" data-density={props.density} data-motion={props.motion === 'reduced' ? 'reduced' : undefined} data-theme={props.theme} style={{ display: 'contents' }}>
    {props.defs !== false && <InkDefs patterns={props.patterns} />}
    {props.textures && <InkTiles tiles={props.textures} />}
    {slots.default?.()}
  </div>
})

import { defineUi } from '@/lib/component'
import { inkViewBox } from '@/lib/ink/builder'
import type { Frame } from './cache'

// 保持原版的图层顺序和 SVG 坐标，只有框架插入 HTML 的方式改用 Vue innerHTML。
