import { Ink, type InkOptions, type Knobs } from '@/lib/ink/builder'
import type { LayerName, Tier } from '@/lib/ink/types'

export type InkLayerName = LayerName | 'indeterminate' | 'open' | 'busy'
export type Density = 'comfortable' | 'compact' | 'calm'
export type Dir = 'ltr' | 'rtl'

export interface Box {
  w: number
  h: number
}

export const INK_LAYER_ORDER: readonly InkLayerName[] = [
  'rest', 'disabled', 'invalid', 'checked', 'indeterminate', 'open', 'busy', 'hover', 'pressed', 'focus',
]

export function orderLayers<T extends string>(names: readonly T[]): T[] {
  const rank = (k: string) => {
    const i = INK_LAYER_ORDER.indexOf(k as InkLayerName)
    return i < 0 ? INK_LAYER_ORDER.length : i
  }
  return [...names].sort((a, b) => rank(a) - rank(b))
}

export interface RecipeContext {
  readonly tier: Tier
  readonly density: Density
  readonly calm: boolean
  readonly knobs: Knobs
  readonly dir: Dir
  readonly seed: string
  wants(layer: InkLayerName): boolean
  lazy(layer: InkLayerName, fn: (ink: Ink) => void): void
  readonly lazyOnly: boolean
}

export interface RecipeDef<P> {
  id: string
  kind?: string
  layers: readonly InkLayerName[]
  lazy?: readonly InkLayerName[]
  pad: number | ((box: Box, params: P, ctx: RecipeContext) => number)
  draw(ink: Ink, box: Box, params: P, ctx: RecipeContext): void
}

export interface Recipe<P = unknown> extends RecipeDef<P> {
  readonly lazy: readonly InkLayerName[]
  readonly kind: string
  readonly isInkRecipe: true
  readonly rev: number
}

const ID_RE = /^[a-z][a-z0-9]*(-[a-z0-9]+)*$/
const registry = new Map<string, Recipe<never>>()

export function defineRecipe<P = Record<string, never>>(def: RecipeDef<P>): Recipe<P> {
  if (!ID_RE.test(def.id)) console.error(`ink recipe id "${def.id}" must be kebab-case (letters, digits, hyphens)`)
  const lazy = def.lazy ?? []
  for (const l of lazy) if (!def.layers.includes(l)) console.error(`ink recipe "${def.id}": lazy layer "${l}" is not in layers`)
  const recipe: Recipe<P> = { ...def, lazy, kind: def.kind ?? def.id, isInkRecipe: true, rev: (registry.get(def.id)?.rev ?? 0) + 1 }
  registry.set(def.id, recipe as unknown as Recipe<never>)
  return recipe
}

export function getRecipe(id: string): Recipe<never> | undefined {
  return registry.get(id)
}

export function allRecipes(): Recipe<never>[] {
  return [...registry.values()]
}

export const DEFAULT_KNOBS: Knobs = { wobble: 1, misreg: 1, bleed: 1, width: 1 }

export function resolveKnobs(themeKnobs: Knobs, density: Density): Knobs {
  if (density === 'calm') return { ...DEFAULT_KNOBS, bleed: themeKnobs.bleed }
  if (density === 'compact') return { ...themeKnobs, misreg: themeKnobs.misreg * 0.85, width: themeKnobs.width * 0.94 }
  return themeKnobs
}

export interface RunRequest<P> {
  box: Box
  params: P
  seed: string
  tier: Tier
  density: Density
  dir: Dir
  knobs: Knobs
  pad?: number
  lazy?: readonly InkLayerName[]
  lazyOnly?: boolean
}

export interface RawFrame {
  parts: Partial<Record<InkLayerName, string>>
  layers: InkLayerName[]
  lazyLayers: InkLayerName[]
  pad: number
  w: number
  h: number
}

export const runCounter = { runs: 0 }

export function runRecipe<P>(recipe: Recipe<P>, req: RunRequest<P>): RawFrame {
  const { box, params } = req
  const calm = req.density === 'calm'
  const tier: Tier = calm ? 'lo' : req.tier
  const wanted = new Set<InkLayerName>(req.lazy ?? [])
  const inkOpts: InkOptions = { tier, calm, knobs: req.knobs }
  const seed = `${req.seed}|${recipe.id}`
  const lazyOnly = req.lazyOnly === true
  const ctxBase = { tier, density: req.density, calm, knobs: req.knobs, dir: req.dir, seed, lazyOnly }
  const lazyParts: Partial<Record<InkLayerName, string>> = {}
  const pad0 = req.pad ?? (typeof recipe.pad === 'number' ? recipe.pad : undefined)
  const ctx: RecipeContext = {
    ...ctxBase,
    wants: (layer) => wanted.has(layer),
    lazy(layer, fn) {
      if (!wanted.has(layer)) return
      const li = new Ink(`${seed}|${layer}`, inkOpts)
      li.layer(layer as LayerName, () => fn(li))
      lazyParts[layer] = li.toSvg({ w: box.w, h: box.h, pad: pad0 ?? 12 }).parts[layer as LayerName] ?? ''
    },
  }
  const ink = new Ink(seed, inkOpts)
  runCounter.runs++
  recipe.draw(ink, box, params, ctx)
  const pad = req.pad ?? (typeof recipe.pad === 'number' ? recipe.pad : recipe.pad(box, params, ctx))
  const parts: Partial<Record<InkLayerName, string>> = {}
  if (!lazyOnly) {
    const res = ink.toSvg({ w: box.w, h: box.h, pad })
    for (const k of res.layers) {
      const markup = res.parts[k]
      if (markup) parts[k as InkLayerName] = markup
    }
  }
  const lazyLayers: InkLayerName[] = []
  for (const k of Object.keys(lazyParts) as InkLayerName[]) {
    if (lazyParts[k]) {
      parts[k] = lazyParts[k]
      lazyLayers.push(k)
    }
  }
  return { parts, layers: orderLayers(Object.keys(parts) as InkLayerName[]), lazyLayers: orderLayers(lazyLayers), pad, w: box.w, h: box.h }
}

let warnedFn = false

export function stableStringify(v: unknown): string {
  if (v === null || typeof v === 'boolean' || typeof v === 'string') return JSON.stringify(v)
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : '"NaN"'
  if (v === undefined) return 'null'
  if (Array.isArray(v)) return `[${v.map(stableStringify).join(',')}]`
  if (typeof v === 'object') {
    const o = v as Record<string, unknown>
    const keys = Object.keys(o).filter((k) => o[k] !== undefined).sort()
    return `{${keys.map((k) => `${JSON.stringify(k)}:${stableStringify(o[k])}`).join(',')}}`
  }
  if (!warnedFn) {
    warnedFn = true
    console.error('ink: recipe params must be plain JSON (found a function or symbol); it cannot be part of the memo key')
  }
  return '"[unhashable]"'
}

export function knobsKey(k: Knobs): string {
  const f = (x: number) => String(Math.round(x * 100) / 100)
  return `${f(k.wobble)},${f(k.misreg)},${f(k.bleed)},${f(k.width)}`
}

export function bucketBox(w: number, h: number, q: readonly [number, number] = [4, 2]): Box {
  return { w: Math.max(q[0], Math.round(w / q[0]) * q[0]), h: Math.max(q[1], Math.round(h / q[1]) * q[1]) }
}

export interface Rng {
  (): number
  readonly seed: number
  range(a: number, b: number): number
  int(a: number, b: number): number
  chance(p: number): boolean
  sign(): 1 | -1
  pick<T>(arr: readonly T[]): T
  gauss(mean?: number, sd?: number): number
  fork(name: string | number): Rng
}

const AVALANCHE = 0x9e3779b9

function avalanche(h: number): number {
  h ^= h >>> 16
  h = Math.imul(h, 0x85ebca6b)
  h ^= h >>> 13
  h = Math.imul(h, 0xc2b2ae35)
  h ^= h >>> 16
  return h >>> 0
}

export function hashSeed(s: string | number): number {
  if (typeof s === 'number') return (Number.isFinite(s) ? avalanche(s >>> 0) : 0) || AVALANCHE
  let h = 0x811c9dc5
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }
  return avalanche(h) || AVALANCHE
}

function derive(base: number, name: string): number {
  let h = (0x811c9dc5 ^ base) >>> 0
  h = Math.imul(h, 0x01000193)
  for (let i = 0; i < name.length; i++) {
    h ^= name.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }
  return avalanche(h) || AVALANCHE
}

function build(base: number): Rng {
  let s = base
  let spare: number | null = null
  const next = (): number => {
    s = (s + 0x6d2b79f5) >>> 0
    let t = s
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
  const rng = next as Rng & { seed: number }
  rng.seed = base
  rng.range = (a, b) => a + (b - a) * next()
  rng.int = (a, b) => a + Math.floor(next() * (b - a + 1))
  rng.chance = (p) => next() < p
  rng.sign = () => (next() < 0.5 ? -1 : 1)
  rng.pick = (arr) => arr[Math.floor(next() * arr.length)]
  rng.gauss = (mean = 0, sd = 1) => {
    if (spare !== null) {
      const v = spare
      spare = null
      return mean + sd * v
    }
    let u = 0
    while (u === 0) u = next()
    const r = Math.sqrt(-2 * Math.log(u))
    const a = 2 * Math.PI * next()
    spare = r * Math.sin(a)
    return mean + sd * r * Math.cos(a)
  }
  rng.fork = (name) => build(derive(base, String(name)))
  return rng
}

export function makeRng(seed: string | number): Rng {
  return build(hashSeed(seed))
}

export const clamp = (v: number, a: number, b: number): number => (v < a ? a : v > b ? b : v)
export const lerp = (a: number, b: number, t: number): number => a + (b - a) * t
export const smooth = (t: number): number => (t <= 0 ? 0 : t >= 1 ? 1 : t * t * (3 - 2 * t))

import type { Line, PenName, PenSpec, Pt, StrokeOpts } from '@/lib/ink/types'
import type { Ink } from '@/lib/ink/builder'
import { clamp, type Rng } from '@/lib/ink/rng'
import { TAU, seg } from '@/lib/ink/geom'
import { n } from '@/lib/ink/paint'
import { pen } from '@/lib/ink/pens'

export interface ShapeOpts {
  pen?: PenName | PenSpec
  opts?: StrokeOpts
  loose?: number
}

const dirv = (a: Pt, b: Pt): Pt => {
  const l = Math.hypot(b[0] - a[0], b[1] - a[1]) || 1
  return [(b[0] - a[0]) / l, (b[1] - a[1]) / l]
}

function put(ink: Ink, salt: string, gen: (rng: Rng) => Line[], defaultPen: PenName, o: ShapeOpts): void {
  ink.lines(gen(ink.next(salt)), o.pen ?? defaultPen, o.opts)
}

export function chain(vs: Pt[], bows: number[], rad: number, rng: Rng, cnt = 14): Pt[] {
  const E = vs.length - 1
  const d: Pt[] = [], len: number[] = []
  for (let i = 0; i < E; i++) {
    d.push(dirv(vs[i], vs[i + 1]))
    len.push(Math.hypot(vs[i + 1][0] - vs[i][0], vs[i + 1][1] - vs[i][1]))
  }
  const rv: number[] = new Array(E + 1).fill(0)
  for (let j = 1; j < E; j++) {
    const r = Math.min(rad * (0.75 + rng() * 0.5), len[j - 1] * 0.45, len[j] * 0.45)
    rv[j] = r < 0.6 ? 0 : r
  }
  const out: Pt[] = []
  for (let i = 0; i < E; i++) {
    const s: Pt = [vs[i][0] + d[i][0] * rv[i], vs[i][1] + d[i][1] * rv[i]]
    const e: Pt = [vs[i + 1][0] - d[i][0] * rv[i + 1], vs[i + 1][1] - d[i][1] * rv[i + 1]]
    const pts = seg(s[0], s[1], e[0], e[1], bows[i] || 0, Math.max(2, Math.ceil(Math.hypot(e[0] - s[0], e[1] - s[1]) / cnt)))
    if (i > 0 && rv[i] === 0) pts.shift()
    out.push(...pts)
    if (i < E - 1 && rv[i + 1] > 0) {
      const V = vs[i + 1], r = rv[i + 1]
      const a = e
      const b: Pt = [V[0] + d[i + 1][0] * r, V[1] + d[i + 1][1] * r]
      const k = 0.9 + rng() * 0.1
      const c: Pt = [V[0] * k + ((a[0] + b[0]) / 2) * (1 - k), V[1] * k + ((a[1] + b[1]) / 2) * (1 - k)]
      for (let j = 1; j < 4; j++) {
        const t = j / 4, u = 1 - t
        out.push([u * u * a[0] + 2 * u * t * c[0] + t * t * b[0], u * u * a[1] + 2 * u * t * c[1] + t * t * b[1]])
      }
    }
  }
  return out
}

export const RULER: StrokeOpts = { poly: true, raw: true, start: 'soft', end: 'soft', speed: 1, dry: 0 }

export function lineLines(x1: number, y1: number, x2: number, y2: number): Line[] {
  return [{ pts: [[x1, y1], [x2, y2]], o: RULER }]
}
export function line(ink: Ink, x1: number, y1: number, x2: number, y2: number, o: ShapeOpts = {}): void {
  put(ink, 'line', () => lineLines(x1, y1, x2, y2), 'pencil', o)
}

export function squiggleLines(rng: Rng, x: number, y: number, w: number, o: { h?: number; amp?: number; wl?: number } = {}): Line[] {
  const h = o.h ?? 12
  const amp = clamp(h * 0.2, 1.4, 3.2) * (o.amp ?? 1), wl = clamp(h * 1.1, 10, 18) * (o.wl ?? 1)
  const p1 = rng.range(0, TAU), p2 = rng.range(0, TAU), p3 = rng.range(0, TAU)
  const drift = rng.gauss(0, 0.6)
  const build = (xa: number, xb: number): Pt[] => {
    const pts: Pt[] = []
    let ph = rng.range(0, TAU)
    for (let xx = xa; xx <= xb; xx += 1.8) {
      ph += (1.8 / wl) * TAU * (1 + 0.22 * Math.sin(xx / 37 + p1) + 0.1 * Math.sin(xx / 11 + p2))
      const a = amp * (0.72 + 0.28 * Math.sin(xx / 53 + p3) + 0.12 * Math.sin(xx / 17 + p1))
      pts.push([xx, y + Math.sin(ph) * a + drift * Math.sin(((xx - x) / w) * Math.PI)])
    }
    return pts.filter((_, i) => i % 2 === 0)
  }
  if (w > 300) {
    const m = x + w * rng.range(0.46, 0.6)
    return [
      { pts: build(x, m + 3), o: { start: 'soft', end: 'soft', wobble: 0.5, speed: 1.1 } },
      { pts: build(m - 3, x + w), o: { start: 'soft', end: 'flick', wobble: 0.5, speed: 1.1 } },
    ]
  }
  return [{ pts: build(x, x + w), o: { end: 'flick', wobble: 0.5, speed: 1.1 } }]
}
export function squiggle(ink: Ink, x: number, y: number, w: number, o: ShapeOpts & { h?: number; amp?: number; wl?: number } = {}): void {
  put(ink, 'sq', (r) => squiggleLines(r, x, y, w, o), 'ink', o)
}

export function underlineLines(rng: Rng, x: number, y: number, w: number, o: { kind?: 'single' | 'double' | 'wavy' } = {}): Line[] {
  if (o.kind === 'wavy') return squiggleLines(rng, x, y, w, { h: 7, amp: 0.85 })
  const out: Line[] = [{ pts: [[x, y], [x + w, y]], o: RULER }]
  if (o.kind === 'double') out.push({ pts: [[x, y + 3.6], [x + w, y + 3.6]], o: RULER })
  return out
}
export function underline(ink: Ink, x: number, y: number, w: number, o: ShapeOpts & { kind?: 'single' | 'double' | 'wavy' } = {}): void {
  put(ink, 'ul', (r) => underlineLines(r, x, y, w, o), 'ink', o)
}

export function strikeLines(rng: Rng, x: number, y: number, w: number, o: { double?: boolean } = {}): Line[] {
  const tilt = rng.gauss(0, 0.012) * w
  const x1 = x - rng.range(1, 3), x2 = x + w + rng.range(0, 3)
  const so: StrokeOpts = { start: 'soft', end: 'flick', speed: 1.25, wobble: 0.6 }
  const out: Line[] = [{ pts: seg(x1, y + tilt / 2, x2, y - tilt / 2, rng.gauss(0, 0.003) * w, Math.max(3, Math.ceil(w / 16))), o: so }]
  if (o.double) out.push({ pts: seg(x1 + 2, y + 2.5, x2 - 1, y + 1.5 - tilt, 0, 6), o: so })
  return out
}
export function strike(ink: Ink, x: number, y: number, w: number, o: ShapeOpts & { double?: boolean } = {}): void {
  put(ink, 'st', (r) => strikeLines(r, x, y, w, o), 'red', o)
}

export interface BoxOpts {
  corner?: number
  loose?: number
  wobble?: number
}

export function boxLines(rng: Rng, x: number, y: number, w: number, h: number, o: BoxOpts = {}): Line[] {
  const k = o.loose ?? 1
  const m = Math.min(w, h)
  const jc = clamp(0.012 * m, 0.12, 0.4) * k
  const tilt = rng.gauss(0, 0.0012) * k
  const rad = o.corner ?? clamp(m * 0.09, 0.9, 3.4)
  const C = (px: number, py: number, sy: number): Pt => [px + rng.gauss(0, jc), py + rng.gauss(0, jc) + sy * tilt * w]
  const TL = C(x, y, 0), TR = C(x + w, y, 1), BR = C(x + w, y + h, 1), BL = C(x, y + h, 0)
  const lift = (l: number): number => rng.range(0.05, 0.32) * clamp(l / 110, 0.3, 1.2) * k
  const drift = (l: number): number => rng.gauss(0, 0.1) * clamp(l / 40, 0.4, 1) * k
  const t0 = rng.range(0.35, 0.65)
  const S: Pt = [TL[0] + (TR[0] - TL[0]) * t0, TL[1] + (TR[1] - TL[1]) * t0]
  const run = Math.min(0.06 * w, rng.range(1.6, 2.6))
  const vs: Pt[] = [S, TR, BR, BL, TL, [S[0] + run, S[1]]]
  const bows = [-lift(w * (1 - t0)), drift(h), lift(w), drift(h), -lift(w * t0 + run)]
  return [{ pts: chain(vs, bows, rad, rng), o: { speed: 1, wobble: 0.28 * (o.wobble ?? 1), dry: 0, end: 'soft', start: 'soft' } }]
}
export function box(ink: Ink, x: number, y: number, w: number, h: number, o: ShapeOpts & BoxOpts = {}): void {
  put(ink, 'box', (r) => boxLines(r, x, y, w, h, o), 'ink', o)
}

export function loopLines(rng: Rng, cx: number, cy: number, rx: number, ry: number, o: { turns?: number; a0?: number; drift?: number; breathe?: number; loose?: number; clean?: boolean } = {}): Line[] {
  if (o.clean) {
    const a0 = o.a0 ?? rng.range(-2.9, -1.8)
    const steps = Math.max(24, Math.ceil((rx + ry) * 0.6))
    const turn = 1 + 2.2 / Math.max(6, Math.PI * (rx + ry))
    const ph = rng.range(0, TAU)
    const pts: Pt[] = []
    for (let i = 0; i <= steps; i++) {
      const a = a0 + (i / steps) * turn * TAU
      const kk = 1 + 0.006 * Math.sin(2 * a + ph)
      pts.push([cx + Math.cos(a) * rx * kk, cy + Math.sin(a) * ry * kk])
    }
    return [{ pts, o: { end: 'soft', start: 'soft', wobble: 0.25, speed: 1, dry: 0 } }]
  }
  const turns = o.turns ?? rng.range(1.05, 1.18)
  const a0 = o.a0 ?? rng.range(-2.9, -1.8)
  const tilt = rng.gauss(0, 0.05) * (o.loose ?? 1)
  const drift = o.drift ?? rng.range(-0.07, 0.05)
  const breathe = o.breathe ?? 0.035
  const ph = rng.range(0, TAU)
  const steps = Math.max(16, Math.ceil((rx + ry) * turns * 0.5))
  const pts: Pt[] = []
  for (let i = 0; i <= steps; i++) {
    const t = i / steps, a = a0 + t * turns * TAU
    const kk = 1 + breathe * Math.sin(2 * a + ph) + drift * t
    const ex = Math.cos(a) * rx * kk, ey = Math.sin(a) * ry * kk
    pts.push([cx + ex * Math.cos(tilt) - ey * Math.sin(tilt), cy + ex * Math.sin(tilt) + ey * Math.cos(tilt)])
  }
  return [{ pts, o: { end: 'flick', start: 'pool', wobble: 0.7, speed: 1 } }]
}
export function loop(ink: Ink, cx: number, cy: number, rx: number, ry: number, o: ShapeOpts & { turns?: number; a0?: number; drift?: number; breathe?: number; clean?: boolean } = {}): void {
  put(ink, 'loop', (r) => loopLines(r, cx, cy, rx, ry, o), 'ink', o)
}

export function arrowLines(rng: Rng, x1: number, y1: number, x2: number, y2: number, o: { head?: 'v' | 'two' | 'open' | 'solid' | 'none'; curl?: boolean; curve?: number; headLen?: number } = {}): Line[] {
  const len = Math.hypot(x2 - x1, y2 - y1)
  const bow = (o.curve ?? rng.range(-0.1, 0.1)) * len
  let shaft = seg(x1, y1, x2, y2, bow, Math.max(6, Math.ceil(len / 8)))
  if (o.curl) {
    const m = Math.floor(shaft.length * 0.5), pm = shaft[m], pn = shaft[m + 1] || pm
    const d0 = dirv(pm, pn), r0 = Math.min(9, len * 0.09)
    const loopPts: Pt[] = []
    for (let i = 0; i <= 14; i++) {
      const a = -Math.PI / 2 + (i / 14) * TAU
      const lx = Math.cos(a) * r0, ly = Math.sin(a) * r0 * 1.15 + r0 * 1.15
      loopPts.push([pm[0] + d0[0] * lx * 1.1 + d0[1] * (ly - r0 * 1.15), pm[1] + d0[1] * lx * 1.1 - d0[0] * (ly - r0 * 1.15)])
    }
    shaft = [...shaft.slice(0, m), ...loopPts, ...shaft.slice(m + 1)]
  }
  const out: Line[] = [{ pts: shaft, o: { end: 'flick', start: 'pool' } }]
  const style = o.head ?? 'v'
  if (style === 'none') return out
  const p = shaft[shaft.length - 1], q = shaft[shaft.length - 3] || shaft[0]
  const d = dirv(q, p)
  const hl = o.headLen ?? clamp(len * 0.2, 6, 12)
  const s1 = rng.range(0.42, 0.6), s2 = rng.range(0.42, 0.6)
  const tip: Pt = [p[0] + rng.gauss(0, 0.3), p[1] + rng.gauss(0, 0.3)]
  const rot = (a: number, l: number): Pt => [tip[0] - (d[0] * Math.cos(a) - d[1] * Math.sin(a)) * l, tip[1] - (d[0] * Math.sin(a) + d[1] * Math.cos(a)) * l]
  const b1 = rot(s1, hl), b2 = rot(-s2, hl * rng.range(0.85, 1.1))
  if (style === 'v') {
    out.push({ pts: [b1, seg(b1[0], b1[1], tip[0], tip[1], rng.gauss(0, 0.3), 3)[1], tip, seg(tip[0], tip[1], b2[0], b2[1], rng.gauss(0, 0.3), 3)[1], b2], o: { end: 'flick', start: 'soft', wobble: 0.5 } })
  } else if (style === 'two') {
    out.push({ pts: seg(b1[0], b1[1], tip[0], tip[1], 0.3, 4), o: { end: 'pool', start: 'soft', wobble: 0.5 } })
    out.push({ pts: seg(tip[0], tip[1], b2[0], b2[1], -0.3, 4), o: { end: 'flick', start: 'soft', wobble: 0.5 } })
  } else if (style === 'open') {
    out.push({ pts: [b1, tip, b2], o: { end: 'soft', start: 'soft', wobble: 0.4, poly: true } })
  } else {
    const toward = (a: Pt, b: Pt, t: number): Pt => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]
    out.push({ pts: [b1, tip, b2, toward(b1, tip, 0.12)], o: { end: 'pool', wobble: 0.3, width: 1.1 } })
    const c: Pt = [(b1[0] + b2[0] + tip[0]) / 3, (b1[1] + b2[1] + tip[1]) / 3]
    out.push({ pts: [toward(b1, c, 0.35), toward(b2, c, 0.3), toward(tip, c, 0.3), c], o: { end: 'pool', wobble: 0.2, width: 1.3 } })
  }
  return out
}
export function arrow(ink: Ink, x1: number, y1: number, x2: number, y2: number, o: ShapeOpts & { head?: 'v' | 'two' | 'open' | 'solid' | 'none'; curl?: boolean; curve?: number; headLen?: number } = {}): void {
  put(ink, 'arrow', (r) => arrowLines(r, x1, y1, x2, y2, o), 'ink', o)
}

export function checkLines(rng: Rng, x: number, y: number, s: number): Line[] {
  const a: Pt = [x + s * rng.range(0, 0.1), y + s * rng.range(0.45, 0.58)]
  const b: Pt = [x + s * rng.range(0.32, 0.42), y + s * rng.range(0.86, 0.96)]
  const c: Pt = [x + s * rng.range(0.9, 1.02), y + s * rng.range(0, 0.1)]
  const mid: Pt = [b[0] + (c[0] - b[0]) * 0.45 - s * 0.05, b[1] + (c[1] - b[1]) * 0.45 + s * 0.02]
  return [{ pts: [...seg(a[0], a[1], b[0], b[1], s * 0.03, 4), mid, c], o: { start: 'pool', end: 'flick', speed: 1.1, wobble: 0.5 } }]
}
export function check(ink: Ink, x: number, y: number, s: number, o: ShapeOpts = {}): void {
  put(ink, 'check', (r) => checkLines(r, x, y, s), 'greenfelt', o)
}

export function crossLines(rng: Rng, x: number, y: number, s: number): Line[] {
  const j = (): number => rng.gauss(0, 0.04 * s)
  return [
    { pts: seg(x + j(), y + j(), x + s + j(), y + s + j(), rng.gauss(0, 0.03 * s), 5), o: { end: 'flick', wobble: 0.5 } },
    { pts: seg(x + s + j(), y + j(), x + j(), y + s + j(), rng.gauss(0, 0.03 * s), 5), o: { end: 'flick', wobble: 0.5 } },
  ]
}
export function cross(ink: Ink, x: number, y: number, s: number, o: ShapeOpts = {}): void {
  put(ink, 'cross', (r) => crossLines(r, x, y, s), 'redfelt', o)
}

export function asteriskLines(rng: Rng, cx: number, cy: number, s: number): Line[] {
  const out: Line[] = []
  for (let k = 0; k < 3; k++) {
    const a = Math.PI / 2 + (k * Math.PI) / 3 + rng.gauss(0, 0.07)
    const l = 0.5 * s * rng.range(0.85, 1)
    const c: Pt = [cx + rng.gauss(0, 0.03 * s), cy + rng.gauss(0, 0.03 * s)]
    out.push({ pts: seg(c[0] - Math.cos(a) * l, c[1] - Math.sin(a) * l, c[0] + Math.cos(a) * l, c[1] + Math.sin(a) * l, rng.gauss(0, 0.3), 4), o: { end: 'flick', wobble: 0.4 } })
  }
  return out
}
export function asterisk(ink: Ink, cx: number, cy: number, s: number, o: ShapeOpts = {}): void {
  put(ink, 'ast', (r) => asteriskLines(r, cx, cy, s), 'redfelt', o)
}

export function spiralLines(rng: Rng, cx: number, cy: number, r0: number, o: { turns?: number; steps?: number; shrink?: number } = {}): Line[] {
  const turns = o.turns ?? 2.3
  const steps = o.steps ?? 26
  const a0 = rng.range(0, TAU)
  const pts: Pt[] = []
  for (let i = 0; i <= steps; i++) {
    const t = i / steps
    const r = r0 * (1 - (o.shrink ?? 0.78) * t)
    const a = a0 + t * turns * TAU + rng.range(0, 0.2)
    pts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r * 0.94])
  }
  return [{ pts, o: { end: 'pool', start: 'soft', wobble: 0.3, speed: 0.9 } }]
}
export function spiral(ink: Ink, cx: number, cy: number, r: number, o: ShapeOpts & { turns?: number; steps?: number; shrink?: number } = {}): void {
  put(ink, 'spiral', (rg) => spiralLines(rg, cx, cy, r, o), 'ink', o)
}

export function starLines(rng: Rng, cx: number, cy: number, r: number): Line[] {
  const pts: Pt[] = []
  const a0 = -Math.PI / 2 + rng.gauss(0, 0.06)
  for (let i = 0; i <= 5; i++) {
    const a = a0 + ((i * 2) % 5) * (TAU / 5)
    const rr = r * rng.range(0.9, 1.05)
    pts.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr])
  }
  pts.push([pts[0][0] + rng.gauss(0, 0.05 * r) + 0.1 * r, pts[0][1] + 0.18 * r])
  return [{ pts, o: { poly: true, wobble: 0.5, end: 'flick' } }]
}
export function star(ink: Ink, cx: number, cy: number, r: number, o: ShapeOpts = {}): void {
  put(ink, 'star', (rg) => starLines(rg, cx, cy, r), 'ink', o)
}

export function tallyLines(rng: Rng, x: number, y: number, count: number, gh: number): { lines: Line[]; width: number } {
  const step = 0.26 * gh, gw = 1.05 * gh + 6
  const lines: Line[] = []
  let gx = x
  let left = count
  while (left > 0) {
    const n5 = Math.min(5, left)
    left -= n5
    const up = Math.min(4, n5)
    for (let i = 0; i < up; i++) {
      const lx = gx + i * step + rng.gauss(0, 0.35)
      lines.push({ pts: seg(lx + rng.gauss(0.4, 0.4), y + rng.gauss(0, 0.5), lx - rng.gauss(0.3, 0.3), y + gh + rng.gauss(0, 0.6), rng.gauss(0, 0.4), 4), o: { end: rng.chance(0.5) ? 'flick' : 'pool', speed: 1.15, wobble: 0.5 } })
    }
    if (n5 === 5) lines.push({ pts: seg(gx - 0.55 * step, y + 0.78 * gh + rng.gauss(0, 0.6), gx + 3.55 * step, y + 0.2 * gh + rng.gauss(0, 0.6), rng.gauss(0, 0.5), 5), o: { end: 'flick', speed: 1.25, wobble: 0.5 } })
    gx += gw
  }
  return { lines, width: gx - x }
}
export function tally(ink: Ink, x: number, y: number, count: number, gh: number, o: ShapeOpts = {}): number {
  const t = tallyLines(ink.next('tally'), x, y, count, gh)
  ink.lines(t.lines, o.pen ?? 'ink', o.opts)
  return t.width
}

export function bracketLines(rng: Rng, x: number, y: number, h: number, o: { kind?: 'square' | 'curly' | 'round'; dir?: 1 | -1 } = {}): Line[] {
  const d = o.dir ?? 1
  const tip = clamp(h * 0.12, 3, 9)
  const kind = o.kind ?? 'square'
  const so: StrokeOpts = { end: 'flick', wobble: 0.5 }
  if (kind === 'square') {
    const rad = Math.min(0.35 * tip, 2.2)
    const pts: Pt[] = [
      [x + d * tip * rng.range(0.85, 1.1), y + rng.gauss(0, 0.5)],
      [x + d * rad, y + rng.gauss(0, 0.2)],
      [x + rng.gauss(0, 0.2), y + rad],
      ...seg(x + rng.gauss(0, 0.2), y + rad, x + rng.gauss(0, 0.6), y + h - rad, rng.gauss(0, 0.004) * h, 6).slice(1),
      [x + d * rad, y + h + rng.gauss(0, 0.2)],
      [x + d * tip * rng.range(0.85, 1.15), y + h + rng.gauss(0, 0.6)],
    ]
    return [{ pts, o: so }]
  }
  if (kind === 'curly') {
    const m = y + h * rng.range(0.47, 0.53)
    return [{ pts: [[x + d * tip, y], [x + 0.35 * d * tip, y + 0.06 * h], [x + 0.3 * d * tip, m - 0.12 * h], [x - 0.15 * d * tip, m], [x + 0.3 * d * tip, m + 0.12 * h], [x + 0.35 * d * tip, y + h * 0.94], [x + d * tip, y + h]], o: so }]
  }
  const pts: Pt[] = []
  for (let i = 0; i <= 12; i++) {
    const t = i / 12
    pts.push([x + d * tip * (1 - Math.sin(Math.PI * t)), y + h * t])
  }
  return [{ pts, o: so }]
}
export function bracket(ink: Ink, x: number, y: number, h: number, o: ShapeOpts & { kind?: 'square' | 'curly' | 'round'; dir?: 1 | -1 } = {}): void {
  put(ink, 'br', (r) => bracketLines(r, x, y, h, o), 'pencil', o)
}

export function cloudLines(rng: Rng, cx: number, cy: number, w: number, h: number, o: { bulge?: number } = {}): Line[] {
  const rx = w / 2, ry = h / 2
  const bumps = clamp(Math.round((Math.PI * (rx + ry)) / clamp(0.32 * Math.min(w, h), 9, 26)), 6, 40)
  const a0 = -Math.PI / 2 + rng.gauss(0, 0.3)
  const sizes = Array.from({ length: bumps }, () => rng.range(0.75, 1.25))
  const tot = sizes.reduce((a, b) => a + b, 0)
  const pts: Pt[] = []
  let a = a0
  const P = (ang: number): Pt => [cx + Math.cos(ang) * rx, cy + Math.sin(ang) * ry]
  for (let i = 0; i < bumps + 1; i++) {
    const i2 = i % bumps
    const da = (sizes[i2] / tot) * TAU
    const p0 = P(a), p1 = P(a + da)
    const L = Math.hypot(p1[0] - p0[0], p1[1] - p0[1])
    const bulge = Math.min(0.42 * L, o.bulge ?? L * 0.3) * rng.range(0.8, 1.1)
    const nx = (p0[0] + p1[0]) / 2 - cx, ny = (p0[1] + p1[1]) / 2 - cy
    const nl = Math.hypot(nx, ny) || 1
    for (let k = i === 0 ? 0 : 1; k <= 6; k++) {
      const t = k / 6, b = Math.sin(Math.PI * t) * bulge
      pts.push([p0[0] + (p1[0] - p0[0]) * t + (nx / nl) * b, p0[1] + (p1[1] - p0[1]) * t + (ny / nl) * b])
    }
    a += da
  }
  pts.push([pts[1][0] + 1.5, pts[1][1] + 0.6])
  return [{ pts, o: { end: 'flick', wobble: 0.5, speed: 1.05 } }]
}
export function cloud(ink: Ink, cx: number, cy: number, w: number, h: number, o: ShapeOpts & { bulge?: number } = {}): void {
  put(ink, 'cloud', (r) => cloudLines(r, cx, cy, w, h, o), 'pencil', o)
}

export function scribbleLines(rng: Rng, x: number, y: number, w: number, h: number): Line[] {
  const step = Math.max(2.2, 0.28 * h)
  const nn = Math.max(3, Math.round(w / step))
  const lean = rng.gauss(0.18, 0.08) * h
  const pts: Pt[] = []
  for (let k = 0; k <= nn; k++) {
    const up = k % 2 === 0
    pts.push([clamp(x + (k / nn) * w + rng.gauss(0, 0.18 * step) + (up ? -lean / 2 : lean / 2), x, x + w), up ? y + rng.range(0, 0.2) * h : y + rng.range(0.8, 1) * h])
  }
  return [{ pts, o: { end: 'flick', speed: 1.3, wobble: 0.6 } }]
}
export function scribble(ink: Ink, x: number, y: number, w: number, h: number, o: ShapeOpts = {}): void {
  put(ink, 'scrib', (r) => scribbleLines(r, x, y, w, h), 'red', o)
}

export function burstLines(rng: Rng, cx: number, cy: number, r: number, o: { rays?: number } = {}): Line[] {
  const k = o.rays ?? 10
  const a0 = rng.range(0, TAU)
  const out: Line[] = []
  for (let i = 0; i < k; i++) {
    const a = a0 + (i / k) * TAU + rng.gauss(0, 0.07)
    const r0 = r * rng.range(0.42, 0.52), r1 = r * (i % 2 ? rng.range(0.78, 0.9) : rng.range(0.98, 1.1))
    out.push({ pts: seg(cx + Math.cos(a) * r0, cy + Math.sin(a) * r0, cx + Math.cos(a) * r1, cy + Math.sin(a) * r1, rng.gauss(0, 0.25), 3), o: { end: 'flick', start: 'soft', wobble: 0.3, speed: 1.2 } })
  }
  return out
}
export function burst(ink: Ink, cx: number, cy: number, r: number, o: ShapeOpts & { rays?: number } = {}): void {
  put(ink, 'burst', (rg) => burstLines(rg, cx, cy, r, o), 'redfelt', o)
}

export interface FocusRingOpts {
  shape?: 'rect' | 'ellipse'
  gap?: number
  r?: number
  ticks?: boolean
}

export function focusRingLines(rng: Rng, x: number, y: number, w: number, h: number, o: FocusRingOpts = {}): Line[] {
  const gap = o.gap ?? 4
  const out: Line[] = []
  const rect = (o.shape ?? 'rect') === 'rect'
  const X = x - gap, Y = y - gap, W = w + gap * 2, H = h + gap * 2
  if (rect) {
    const R = (o.r ?? 4) + gap
    out.push(...boxLines(rng.fork('ring'), X, Y, W, H, { corner: R }))
  } else {
    out.push(...loopLines(rng.fork('ring'), x + w / 2, y + h / 2, W / 2, H / 2, { clean: true }))
  }
  if (o.ticks === true) {
    const tr = rng.fork('ticks')
    if (rect) {
      const cs: Array<[number, number, number, number]> = [[X, Y, -1, -1], [X + W, Y, 1, -1], [X + W, Y + H, 1, 1], [X, Y + H, -1, 1]]
      const inset = ((o.r ?? 4) + gap) * (1 - Math.SQRT1_2)
      for (const [cx, cy, sx, sy] of cs) {
        if (tr() < 0.15) continue
        const a = Math.atan2(sy, sx) + tr.gauss(0, 0.15)
        const r0 = 2 + inset, r1 = r0 + 3 + tr() * 2.5
        out.push({ pts: seg(cx + Math.cos(a) * r0, cy + Math.sin(a) * r0, cx + Math.cos(a) * r1, cy + Math.sin(a) * r1, 0.3, 3), o: { end: 'flick', start: 'soft', wobble: 0.3, width: 0.8 } })
      }
    } else {
      const cx = x + w / 2, cy = y + h / 2
      for (const base of [-0.75 * Math.PI, 0.25 * Math.PI]) {
        const a = base + tr.gauss(0, 0.2)
        const ex = Math.cos(a), ey = Math.sin(a)
        const r0 = Math.hypot(ex * (W / 2), ey * (H / 2)) + 2, r1 = r0 + 3 + tr() * 2.5
        out.push({ pts: seg(cx + ex * r0, cy + ey * r0, cx + ex * r1, cy + ey * r1, 0.3, 3), o: { end: 'flick', start: 'soft', wobble: 0.3, width: 0.8 } })
      }
    }
  }
  return out
}
export function focusRing(ink: Ink, x: number, y: number, w: number, h: number, o: ShapeOpts & FocusRingOpts = {}): void {
  put(ink, 'focus', (r) => focusRingLines(r, x, y, w, h, o), 'focus', o)
}

export function dashedBoxLines(rng: Rng, x: number, y: number, w: number, h: number, o: { r?: number; dash?: number; gap?: number } = {}): Line[] {
  const r = Math.min(o.r ?? 4, w / 2, h / 2)
  const cornerPts: Pt[] = []
  const per = 5
  const arc = (cx: number, cy: number, a0: number): void => {
    for (let i = 0; i <= per; i++) {
      const a = a0 + (i / per) * (Math.PI / 2)
      cornerPts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r])
    }
  }
  if (r < 0.5) cornerPts.push([x, y], [x + w, y], [x + w, y + h], [x, y + h])
  else {
    arc(x + w - r, y + r, -Math.PI / 2)
    arc(x + w - r, y + h - r, 0)
    arc(x + r, y + h - r, Math.PI / 2)
    arc(x + r, y + r, Math.PI)
  }
  const closed = [...cornerPts, cornerPts[0]]
  const cum = [0]
  for (let i = 1; i < closed.length; i++) cum.push(cum[i - 1] + Math.hypot(closed[i][0] - closed[i - 1][0], closed[i][1] - closed[i - 1][1]))
  const per_ = cum[cum.length - 1]
  const at = (d: number): Pt => {
    d = ((d % per_) + per_) % per_
    let i = 1
    while (i < cum.length - 1 && cum[i] < d) i++
    const t = (d - cum[i - 1]) / (cum[i] - cum[i - 1] || 1)
    return [closed[i - 1][0] + (closed[i][0] - closed[i - 1][0]) * t, closed[i - 1][1] + (closed[i][1] - closed[i - 1][1]) * t]
  }
  const dash = o.dash ?? clamp(Math.min(w, h) * 0.3, 5, 9), gap = o.gap ?? dash * 0.55
  const count = Math.max(4, Math.round(per_ / (dash + gap)))
  const step = per_ / count
  const len = step * (dash / (dash + gap))
  const d0 = rng() * step
  const out: Line[] = []
  for (let i = 0; i < count; i++) {
    const d = d0 + i * step
    const pts: Pt[] = []
    for (let k = 0; k <= 4; k++) pts.push(at(d + (len * k) / 4))
    out.push({ pts, o: { ...RULER, simple: true } })
  }
  return out
}
export function dashedBox(ink: Ink, x: number, y: number, w: number, h: number, o: ShapeOpts & { r?: number; dash?: number; gap?: number } = {}): void {
  const P = pen(o.pen ?? 'pencil')
  const color = o.opts?.color ?? P.color
  const sw = P.W * 0.85 * (o.opts?.width ?? 1) * ink.knobs.width
  let d = ''
  for (const l of dashedBoxLines(ink.next('dash'), x, y, w, h, o)) d += 'M' + l.pts.map((p) => `${n(p[0], 100)} ${n(p[1], 100)}`).join('L')
  ink.flat(P.kind === 'pencil' ? 'pencil' : 'felt', d, color, P.alpha * (o.opts?.alpha ?? 1), { stroke: color, sw, bbox: [x - sw, y - sw, x + w + sw, y + h + sw] })
}

import { GRAIN_TILES, type GrainMaskKind, type GrainTile } from '@/lib/ink/textures.generated'
import {
  PAPER_TILES, PAPER_RELIEF, PAPER_SLIP, PAPER_FIBRE, PAPER_CLOUD, PAPER_LINEN, PAPER_KRAFT,
  type PaperTile, type PaperTileName,
} from '@/lib/ink/textures-paper.generated'

export type { GrainMaskKind, GrainTile, PaperTile, PaperTileName }
export { GRAIN_TILES, PAPER_TILES }

export const GRAIN_KINDS = ['felt', 'marker', 'graphite', 'waxy', 'stamp'] as const satisfies readonly GrainMaskKind[]

export const GRAIN_VARIANTS = 6

export function grainPhase(variant: number): { x: number; y: number; rot: 0 | 90 | 180 | 270 } {
  const v = ((Math.trunc(variant) % GRAIN_VARIANTS) + GRAIN_VARIANTS) % GRAIN_VARIANTS
  const rots = [0, 90, 180, 270, 0, 180] as const
  return { x: (v * 0.618034) % 1, y: (v * 0.381966 + 0.17) % 1, rot: rots[v] }
}

const idPrefix = (p?: string) => p ?? 'll'
const num = (v: number) => String(Math.round(v * 100) / 100)

export function grainMaskId(kind: GrainMaskKind, variant?: number, prefix?: string): string {
  if (variant === undefined) return `${idPrefix(prefix)}-${kind}`
  return `${idPrefix(prefix)}-${kind}-${((Math.trunc(variant) % GRAIN_VARIANTS) + GRAIN_VARIANTS) % GRAIN_VARIANTS}`
}

export const grainMaskUrl = (kind: GrainMaskKind, variant?: number, prefix?: string) => `url(#${grainMaskId(kind, variant, prefix)})`

export const grainVariantFor = (seed: number): number => (Math.imul(seed | 0, 0x9e3779b1) >>> 7) % GRAIN_VARIANTS

export interface MaskDefsOptions {
  kinds?: readonly GrainMaskKind[]
  prefix?: string
  region?: { x: number; y: number; width: number; height: number } | 'bbox'
}

const DEFAULT_REGION = { x: -2048, y: -2048, width: 8192, height: 8192 }

export function svgMaskDefs(o: MaskDefsOptions = {}): string {
  const kinds = o.kinds ?? GRAIN_KINDS
  const p = idPrefix(o.prefix)
  const region = o.region ?? DEFAULT_REGION
  const maskAttrs = region === 'bbox' ? 'x="-0.1" y="-0.1" width="1.2" height="1.2"' : `maskUnits="userSpaceOnUse" x="${region.x}" y="${region.y}" width="${region.width}" height="${region.height}"`
  const fill = region === 'bbox' ? { x: -4000, y: -4000, width: 9000, height: 9000 } : region
  let s = ''
  for (const kind of kinds) {
    const t = GRAIN_TILES[kind]
    s += `<image id="${p}-${kind}-img" width="${t.css}" height="${t.css}" href="${t.uri}"/>`
    for (let v = 0; v < GRAIN_VARIANTS; v++) {
      const ph = grainPhase(v)
      const tf = ` patternTransform="translate(${num(ph.x * t.css)} ${num(ph.y * t.css)})${ph.rot ? ` rotate(${ph.rot})` : ''}"`
      s += `<pattern id="${p}-${kind}-pat-${v}" width="${t.css}" height="${t.css}" patternUnits="userSpaceOnUse"${tf}><use href="#${p}-${kind}-img"/></pattern>`
    }
    const rect = (v: number) => `<rect x="${fill.x}" y="${fill.y}" width="${fill.width}" height="${fill.height}" fill="url(#${p}-${kind}-pat-${v})"/>`
    s += `<mask id="${p}-${kind}" ${maskAttrs}>${rect(0)}</mask>`
    for (let v = 0; v < GRAIN_VARIANTS; v++) s += `<mask id="${p}-${kind}-${v}" ${maskAttrs}>${rect(v)}</mask>`
  }
  return s
}

export const PAPER_STOCKS = {
  paper: 'var(--ll-paper)',
  slip: 'var(--ll-slip)',
  card: 'var(--ll-card)',
  graph: 'var(--ll-graph)',
  check: 'var(--ll-check)',
  kraft: 'var(--ll-kraft)',
  yellow: 'var(--ll-sticky-yellow)',
  green: 'var(--ll-sticky-green)',
  orange: 'var(--ll-sticky-orange)',
  pink: 'var(--ll-sticky-pink)',
  blue: 'var(--ll-sticky-blue)',
} as const

export type PaperStock = keyof typeof PAPER_STOCKS | (string & {})

export interface TextureStyle {
  backgroundColor: string
  backgroundImage: string
  backgroundSize: string
  backgroundPosition: string
  backgroundRepeat: string
}

export interface PaperBackgroundOptions {
  tooth?: 'cold' | 'fine'
  seed?: string | number
  layers?: Partial<Record<'relief' | 'slip' | 'fibre' | 'cloud' | 'kraft', boolean>>
}

function hash32(seed: string | number): number {
  let h = 0x811c9dc5
  const s = String(seed)
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }
  h ^= h >>> 16
  h = Math.imul(h, 0x85ebca6b)
  h ^= h >>> 13
  return h >>> 0
}

function offsetFor(seed: string | number | undefined, i: number, w: number, h: number): string {
  if (seed === undefined) return '0 0'
  const a = hash32(`${seed}:${i}`)
  return `${-(a % Math.round(w))}px ${-((a >>> 11) % Math.round(h))}px`
}

const url = (uri: string) => `url(${uri})`
const tileSize = (t: PaperTile) => `${t.cssWidth}px ${t.cssHeight}px`

export function paperBackground(stock: PaperStock = 'paper', o: PaperBackgroundOptions = {}): TextureStyle {
  const cold = (o.tooth ?? (stock === 'paper' ? 'cold' : 'fine')) === 'cold'
  const on = { relief: cold && stock !== 'kraft', slip: !cold && stock !== 'kraft', fibre: true, cloud: true, kraft: stock === 'kraft', ...o.layers }
  const order: PaperTileName[] = (['fibre', 'kraft', 'relief', 'slip', 'cloud'] as const).filter((n) => on[n])
  const byName = { relief: PAPER_RELIEF, slip: PAPER_SLIP, fibre: PAPER_FIBRE, cloud: PAPER_CLOUD, kraft: PAPER_KRAFT } as Partial<Record<PaperTileName, PaperTile>>
  const tiles = order.map((n) => byName[n]!)
  const color = (PAPER_STOCKS as Record<string, string>)[stock] ?? stock
  return {
    backgroundColor: color,
    backgroundImage: tiles.map((t) => url(t.uri)).join(', '),
    backgroundSize: tiles.map(tileSize).join(', '),
    backgroundPosition: tiles.map((t, i) => offsetFor(o.seed, i, t.cssWidth, t.cssHeight)).join(', '),
    backgroundRepeat: tiles.map(() => 'repeat').join(', '),
  }
}

export interface DeskBackgroundOptions {
  vignette?: number
  seed?: string | number
}

export function deskBackground(o: DeskBackgroundOptions = {}): TextureStyle {
  const v = o.vignette ?? 0.05
  const vig = `radial-gradient(ellipse 92% 82% at 50% 40%, rgb(var(--ll-shade) / 0) 52%, rgb(var(--ll-shade) / ${v}) 100%)`
  const linen = PAPER_LINEN
  return {
    backgroundColor: 'var(--ll-desk)',
    backgroundImage: [vig, url(linen.uri)].join(', '),
    backgroundSize: ['100% 100%', tileSize(linen)].join(', '),
    backgroundPosition: ['0 0', offsetFor(o.seed, 0, linen.cssWidth, linen.cssHeight)].join(', '),
    backgroundRepeat: ['no-repeat', 'repeat'].join(', '),
  }
}

export function styleToCss(s: TextureStyle): string {
  return `background-color:${s.backgroundColor};background-image:${s.backgroundImage};background-size:${s.backgroundSize};background-position:${s.backgroundPosition};background-repeat:${s.backgroundRepeat}`
}

export const paperCss = (stock?: PaperStock, o?: PaperBackgroundOptions) => styleToCss(paperBackground(stock, o))

export const deskCss = (o?: DeskBackgroundOptions) => styleToCss(deskBackground(o))

export function textureCssVars(names: readonly PaperTileName[] = ['relief', 'slip', 'fibre', 'cloud', 'mottle', 'linen', 'kraft']): string {
  return `:root{${names.map((n) => `--ll-tex-${n}:${url(PAPER_TILES[n].uri)}`).join(';')}}`
}

export interface PatternDefsOptions {
  tiles?: readonly PaperTileName[]
  prefix?: string
}

export const PATTERN_OFFSETS = [
  [0, 0],
  [67, 113],
  [131, 29],
  [23, 171],
] as const

export function svgPatternDefs(o: PatternDefsOptions = {}): string {
  const names = o.tiles ?? (['relief', 'slip', 'fibre', 'cloud', 'mottle', 'linen', 'kraft'] as const)
  const p = idPrefix(o.prefix)
  let s = ''
  for (const name of names) {
    const t = PAPER_TILES[name]
    s += `<image id="${p}-tex-${name}-img" width="${t.cssWidth}" height="${t.cssHeight}" href="${t.uri}"/>`
    PATTERN_OFFSETS.forEach(([x, y], i) => {
      const id = i === 0 ? `${p}-tex-${name}` : `${p}-tex-${name}-${i}`
      const tf = i === 0 ? '' : ` patternTransform="translate(${x} ${y})"`
      s += `<pattern id="${id}" width="${t.cssWidth}" height="${t.cssHeight}" patternUnits="userSpaceOnUse"${tf}><use href="#${p}-tex-${name}-img"/></pattern>`
    })
  }
  return s
}

export function inkDefsSvg(o: MaskDefsOptions & { paper?: boolean } = {}): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false"><defs>${svgMaskDefs(o)}${o.paper ? svgPatternDefs({ prefix: o.prefix }) : ''}</defs></svg>`
}

export interface TextureBytes {
  png: number
  base64: number
}

export function textureBytes() {
  const of = (uri: string, png: number): TextureBytes => ({ png, base64: uri.length })
  const masks = Object.fromEntries(GRAIN_KINDS.map((k) => [k, of(GRAIN_TILES[k].uri, GRAIN_TILES[k].bytes)])) as Record<GrainMaskKind, TextureBytes>
  const paper = Object.fromEntries((Object.keys(PAPER_TILES) as PaperTileName[]).map((k) => [k, of(PAPER_TILES[k].uri, PAPER_TILES[k].bytes)])) as Record<PaperTileName, TextureBytes>
  const sum = (r: Record<string, TextureBytes>) => Object.values(r).reduce((a, b) => ({ png: a.png + b.png, base64: a.base64 + b.base64 }), { png: 0, base64: 0 })
  return { masks, paper, totals: { masks: sum(masks), paper: sum(paper) } }
}

import { hashSeed } from '@/lib/ink/rng'
import { measureText } from '@/lib/ink/art/glyph-text'
import type { ArtColour, ArtDef, BadgeGen, Part } from '@/lib/ink/art/types'

export type BadgeOpts = Partial<Omit<BadgeGen, 'gen' | 'text' | 'kind'>> & { fill?: ArtColour }

const r1 = (v: number): number => Math.round(v * 10) / 10
const rad = (d: number): number => (d * Math.PI) / 180

function lcg(seed: number): () => number {
  let s = (seed % 2147483646) + 1
  return () => ((s = (s * 16807) % 2147483647) / 2147483647 - 0.5) * 2
}

function seal(cx: number, cy: number, r0: number, r1_: number, n: number, rot: number, jit: number, rnd: () => number): string {
  const V: Array<[number, number]> = []
  const C: Array<[number, number]> = []
  for (let i = 0; i < n; i++) {
    const a0 = rad(rot + (i / n) * 360), a1 = rad(rot + ((i + 1) / n) * 360), am = (a0 + a1) / 2
    V.push([cx + Math.cos(a0) * (r0 + rnd() * jit), cy + Math.sin(a0) * (r0 + rnd() * jit)])
    C.push([cx + Math.cos(am) * (r1_ + rnd() * jit), cy + Math.sin(am) * (r1_ + rnd() * jit)])
  }
  let d = `M${r1(V[0][0])} ${r1(V[0][1])}`
  for (let i = 0; i < n; i++) d += ` Q${r1(C[i][0])} ${r1(C[i][1])} ${r1(V[(i + 1) % n][0])} ${r1(V[(i + 1) % n][1])}`
  return d + ' Z'
}

function burst(cx: number, cy: number, ro: number, ri: number, n: number, rot: number, jit: number, rnd: () => number): string {
  let d = ''
  for (let i = 0; i < n * 2; i++) {
    const a = rad(rot + (i / (n * 2)) * 360 + rnd() * 1.5)
    const rr = (i % 2 ? ri : ro) + rnd() * jit
    d += `${i ? ' L' : 'M'}${r1(cx + Math.cos(a) * rr)} ${r1(cy + Math.sin(a) * rr)}`
  }
  return d + ' Z'
}

const j = (v: number, rnd: () => number, a = 0.35): number => r1(v + rnd() * a)

interface Shape {
  outline: string
  under?: Part[]
  ring?: string
  text: { x: number; y: number; w: number; em: number }
  sub?: { y: number; w: number }
  over?: Part[]
  deco: { x: number; y: number }
}

function shapeOf(kind: NonNullable<BadgeGen['shape']>, o: BadgeOpts, rnd: () => number): Shape {
  const bumps = o.bumps ?? 12
  const amp = o.amp ?? 3.6
  switch (kind) {
    case 'scallop': {
      const R = 24.4
      return {
        outline: seal(32, 32, R, R + amp, bumps, 6, 0.3, rnd),
        ring: `O 32 32 ${j(19.6, rnd, 0.2)}`,
        text: { x: 32, y: 34, w: 30, em: 21 },
        sub: { y: 45.4, w: 22 },
        deco: { x: 32, y: 21.2 },
      }
    }
    case 'starburst': {
      const n = o.bumps ?? 16
      return {
        outline: burst(32, 32, 26, 21.4, n, -90, 0.4, rnd),
        ring: `O 32 32 ${j(17.6, rnd, 0.2)}`,
        text: { x: 32, y: 33, w: 27, em: 20 },
        sub: { y: 43.5, w: 22 },
        deco: { x: 32, y: 19.6 },
      }
    }
    case 'rosette':
      return {
        outline: seal(32, 26.5, 17.6, 20, o.bumps ?? 16, 4, 0.2, rnd),
        under: [['f', 'tomato', `M21 40.4 L15.4 57.2 L22.4 53.4 L26.6 57.8 L30 43.4 Z`], ['f', 'tomato', `M43 40.4 L48.6 57.2 L41.6 53.4 L37.4 57.8 L34 43.4 Z`], ['s', 'M21 40.4 L15.4 57.2 L22.4 53.4 L26.6 57.8 L30 43.4', 0.9], ['s', 'M43 40.4 L48.6 57.2 L41.6 53.4 L37.4 57.8 L34 43.4', 0.9]],
        ring: `O 32 26.5 ${j(13.6, rnd, 0.2)}`,
        text: { x: 32, y: 28.4, w: 22, em: 16 },
        sub: { y: 38.4, w: 15 },
        deco: { x: 32, y: 17 },
      }
    case 'plate':
      return {
        outline: `M18 ${j(21, rnd)} L46 ${j(20.6, rnd)} Q${j(57.6, rnd)} 21 ${j(57.6, rnd)} 32 Q${j(57.4, rnd)} 43.4 46 43 L18 ${j(43.4, rnd)} Q6.4 43.4 ${j(6.6, rnd)} 32 Q6.4 20.6 18 ${j(21, rnd)} Z`,
        ring: `M15 ${j(24.4, rnd)} L49 ${j(24, rnd)} Q${j(55.6, rnd)} 24 ${j(55.6, rnd)} 32 Q${j(55.4, rnd)} 40 49 ${j(39.8, rnd)} L15 ${j(40, rnd)} Q8.4 40 8.6 32 Q8.4 24.2 15 ${j(24.4, rnd)} Z`,
        text: { x: 32, y: 32.6, w: 38, em: 15 },
        deco: { x: 32, y: 26 },
      }
    case 'shield':
      return {
        outline: `M32 ${j(6.4, rnd)} L${j(54.6, rnd)} 13.6 L${j(54.4, rnd)} 34 C${j(54, rnd)} 45.6 44.4 52.6 32 ${j(57.4, rnd)} C${j(19.6, rnd)} 52.8 ${j(9.8, rnd)} 45.6 ${j(9.8, rnd)} 34 L${j(9.6, rnd)} 13.4 Z`,
        ring: `M32 ${j(11, rnd)} L${j(48.8, rnd)} 17 L${j(48.6, rnd)} 33.6 C48.4 42 41 47.4 32 ${j(51.8, rnd)} C${j(23, rnd)} 47.4 ${j(15.4, rnd)} 42 15.4 33.6 L${j(15.2, rnd)} 17 Z`,
        text: { x: 32, y: 32.4, w: 26, em: 19 },
        sub: { y: 43, w: 19 },
        deco: { x: 32, y: 21 },
      }
    case 'ticket':
      return {
        outline: `M7 ${j(16, rnd)} L57 ${j(15.6, rnd)} L57 28.4 Q52.4 32 57 35.6 L57 ${j(48, rnd)} L7 ${j(48.4, rnd)} L7 35.6 Q11.6 32 7 28.4 Z`,
        ring: `M12.4 ${j(20.6, rnd)} L51.6 ${j(20.4, rnd)} L51.6 ${j(43.6, rnd)} L12.4 ${j(43.8, rnd)} Z`,
        text: { x: 32, y: 33, w: 34, em: 16 },
        sub: { y: 41.6, w: 30 },
        deco: { x: 32, y: 24.6 },
      }
    case 'banner':
      return {
        outline: `M6.6 ${j(19, rnd)} L12 ${j(19, rnd)} L12 ${j(46.4, rnd)} L6.4 46.6 L9.6 32.6 Z M12 19 L52 ${j(18.6, rnd)} L52 ${j(46, rnd)} L12 46.4 Z M52 18.8 L57.6 ${j(19, rnd)} L54.6 32.6 L57.8 46.4 L52 46.2 Z`,
        text: { x: 32, y: 34, w: 36, em: 16 },
        deco: { x: 32, y: 25 },
      }
    case 'medal':
      return {
        outline: seal(32, 37.4, 18.6, 19.6, 22, 0, 0.2, rnd),
        under: [['f', 'tomato', 'M21.6 6.4 L28 6.8 L34.4 22.6 L27.6 24 Z'], ['f', 'tomato', 'M42.4 6.4 L36 6.8 L29.6 22.6 L36.4 24 Z'], ['s', 'M21.6 6.4 L28 6.8 L34.4 22.6', 0.9], ['s', 'M42.4 6.4 L36 6.8 L29.6 22.6', 0.9]],
        ring: `O 32 37.4 ${j(14.6, rnd, 0.2)}`,
        text: { x: 32, y: 41, w: 21, em: 15 },
        deco: { x: 32, y: 28 },
      }
    case 'tag':
    default:
      return {
        outline: `M23 ${j(14.6, rnd)} L${j(41.6, rnd)} 14.4 L50 ${j(22.6, rnd)} L${j(50.4, rnd)} 57.4 L${j(13.8, rnd)} 57.6 L${j(14.2, rnd)} 22.8 Z`,
        over: [['s', 'O 32 22.4 2.6', 0.8], ['s', 'M32.4 19.8 C31.6 11.2 24 5.4 19.6 8.4 C16.4 10.8 20 16.6 25.6 12.4', 0.85]],
        text: { x: 32, y: 38.6, w: 29, em: 15 },
        sub: { y: 50.6, w: 24 },
        deco: { x: 32, y: 51.4 },
      }
  }
}

const star5 = (cx: number, cy: number, ro: number, ri: number): string => {
  let d = ''
  for (let i = 0; i < 10; i++) {
    const a = rad(-90 + i * 36)
    const rr = i % 2 ? ri : ro
    d += `${i ? ' L' : 'M'}${r1(cx + Math.cos(a) * rr)} ${r1(cy + Math.sin(a) * rr)}`
  }
  return d + ' Z'
}

export function badgeSkeleton(text: string, o: BadgeOpts = {}): ArtDef {
  const kind = o.shape ?? 'scallop'
  const rnd = lcg(hashSeed(`${kind}:${text}:${o.color ?? ''}`))
  const shape = shapeOf(kind, o, rnd)
  const color = o.fill ?? o.color ?? 'bubblegum'
  const ink = o.textColor ?? 'ink'
  const ttl = text.toUpperCase()
  const perEm = measureText('hand', ttl, 1)
  const em = r1(Math.min(shape.text.em, shape.text.w / perEm))
  const capH = 0.745 * em
  const build = (small: boolean): Part[] => {
    const parts: Part[] = []
    if (shape.under) parts.push(...shape.under)
    parts.push(['f', color, shape.outline])
    parts.push(['s', shape.outline, small ? 1.15 : 1.05])
    if (shape.ring) parts.push(['c', 'photo', shape.ring, small ? 0.6 : 0.5], ['s', shape.ring, small ? 0.6 : 0.5])
    if (shape.over) parts.push(...shape.over)
    const sub = !small && o.sub && shape.sub
    const ty = shape.text.y + capH / 2 - (sub ? 2 : 0)
    parts.push(['t', ttl, shape.text.x, r1(ty), em, ink, 'hand'])
    if (sub) parts.push(['t', o.sub!, shape.text.x, shape.sub!.y + 2, r1(Math.min(6.4, shape.sub!.w / measureText('hand', o.sub!.toUpperCase(), 1))), ink, 'hand'])
    if (!small && o.deco) {
      const { x, y } = shape.deco
      if (o.deco === 'tick') parts.push(['s', `M${r1(x - 3.8)} ${r1(y + 0.4)} L${r1(x - 1)} ${r1(y + 3)} L${r1(x + 4.2)} ${r1(y - 3)}`, 0.8])
      else if (o.deco === 'star') parts.push(['f', 'lemon', star5(x, y, 3.6, 1.6)], ['s', star5(x, y, 3.7, 1.6), 0.6])
      else if (o.deco === 'sparkle') parts.push(['s', `M${r1(x + 12)} ${r1(y - 4)} L${r1(x + 12.2)} ${r1(y + 2)} M${r1(x + 9)} ${r1(y - 1)} L${r1(x + 15)} ${r1(y - 1.2)}`, 0.8])
      else if (o.deco === 'swoosh') parts.push(['c', 'tomato', `M${r1(shape.text.x - em * 1.1)} ${r1(ty + 3.4)} Q${r1(shape.text.x)} ${r1(ty + 6)} ${r1(shape.text.x + em * 1.2)} ${r1(ty + 2.4)}`, 0.7])
      else if (o.deco === 'percent') parts.push(['c', ink, `O ${r1(x)} ${r1(y)} 3.4`, 0.55], ['c', ink, `M${r1(x - 2)} ${r1(y + 2)} L${r1(x + 2)} ${r1(y - 2)}`, 0.5])
    }
    return parts
  }
  const master = build(false)
  const small = build(true)
  const def: ArtDef = { grid: 64, nibK: 0.05, parts: master, small, kind: 'sticker' }
  if (o.tags) return { ...def, tags: o.tags }
  return def
}

import type { ArtDef, ArtKind, Part } from '@/lib/ink/art/types'

export type P2 = [number, number]

export interface Sub {
  pts: P2[]
  closed: boolean
  anchor: boolean[]
  shape: number
}

export interface ParseOpts {
  step?: number
  rnd?: () => number
}

const TAU = Math.PI * 2
const TOKEN = /[MLlQCOEZ]|-?(?:\d+\.?\d*|\.\d+)(?:e-?\d+)?/g
const CMD = /^[MLlQCOEZ]$/

export function tokenize(d: string): { tok: string[]; bad: string } {
  const tok = d.match(TOKEN) ?? []
  const bad = d.replace(TOKEN, '').replace(/[\s,]+/g, '')
  return { tok, bad }
}

export function parsePath(d: string, o: ParseOpts = {}): Sub[] {
  const step = o.step ?? 0.6
  const rnd = o.rnd ?? (() => 0.5)
  const { tok } = tokenize(d)
  const subs: Sub[] = []
  let cur: Sub | null = null
  let cx = 0, cy = 0, sx = 0, sy = 0, i = 0
  const num = (): number => Number.parseFloat(tok[i++])
  const isNum = (): boolean => i < tok.length && !CMD.test(tok[i])
  const push = (x: number, y: number, anchor: boolean): void => {
    if (!cur) subs.push((cur = { pts: [], closed: false, anchor: [], shape: 0 }))
    cur.pts.push([x, y])
    cur.anchor.push(anchor)
    cx = x
    cy = y
  }
  while (i < tok.length) {
    const c = tok[i++]
    if (c === 'M') {
      cur = null
      sx = num()
      sy = num()
      push(sx, sy, true)
      while (isNum()) push(num(), num(), true)
    } else if (c === 'L') {
      while (isNum()) push(num(), num(), true)
    } else if (c === 'l') {
      while (isNum()) push(cx + num(), cy + num(), true)
    } else if (c === 'Q') {
      while (isNum()) {
        const x1 = num(), y1 = num(), x2 = num(), y2 = num()
        const x0 = cx, y0 = cy
        const n = Math.max(3, Math.ceil(Math.hypot(x2 - x0, y2 - y0) / step))
        for (let k = 1; k <= n; k++) {
          const t = k / n, u = 1 - t
          push(u * u * x0 + 2 * u * t * x1 + t * t * x2, u * u * y0 + 2 * u * t * y1 + t * t * y2, k === n)
        }
      }
    } else if (c === 'C') {
      while (isNum()) {
        const x1 = num(), y1 = num(), x2 = num(), y2 = num(), x3 = num(), y3 = num()
        const x0 = cx, y0 = cy
        const n = Math.max(4, Math.ceil((Math.hypot(x1 - x0, y1 - y0) + Math.hypot(x2 - x1, y2 - y1) + Math.hypot(x3 - x2, y3 - y2)) / step))
        for (let k = 1; k <= n; k++) {
          const t = k / n, u = 1 - t
          push(
            u * u * u * x0 + 3 * u * u * t * x1 + 3 * u * t * t * x2 + t * t * t * x3,
            u * u * u * y0 + 3 * u * u * t * y1 + 3 * u * t * t * y2 + t * t * t * y3,
            k === n,
          )
        }
      }
    } else if (c === 'O') {
      const ox = num(), oy = num(), rx = num(), ry = isNum() ? num() : rx
      cur = null
      const n = Math.max(20, Math.ceil(((rx + ry) * Math.PI * 1.1) / step))
      const a0 = -2.3 + (rnd() - 0.5) * 0.7
      for (let k = 0; k <= n; k++) {
        const a = a0 + (k / n) * TAU * 1.09
        const kk = 1 + 0.02 * Math.sin(2 * a)
        push(ox + Math.cos(a) * rx * kk, oy + Math.sin(a) * ry * kk, false)
      }
      if (cur) {
        const s = cur as Sub
        s.closed = true
        s.shape = Math.round(n / 1.09)
      }
      sx = (cur as Sub | null)?.pts[0][0] ?? ox
      sy = (cur as Sub | null)?.pts[0][1] ?? oy
    } else if (c === 'E') {
      const ox = num(), oy = num(), rx = num(), ry = num()
      const a0 = (num() * Math.PI) / 180, a1 = (num() * Math.PI) / 180
      const ax = ox + Math.cos(a0) * rx, ay = oy + Math.sin(a0) * ry
      if (!cur || Math.hypot(ax - cx, ay - cy) > 0.8) cur = null
      const n = Math.max(6, Math.ceil((Math.abs(a1 - a0) * Math.max(rx, ry)) / step))
      for (let k = 0; k <= n; k++) {
        const a = a0 + ((a1 - a0) * k) / n
        push(ox + Math.cos(a) * rx, oy + Math.sin(a) * ry, k === 0 || k === n)
      }
    } else if (c === 'Z') {
      const s = cur as Sub | null
      if (s && s.pts.length > 2) {
        s.shape = s.pts.length
        const first = s.pts[0], look = s.pts[Math.min(3, s.pts.length - 1)]
        const dl = Math.hypot(look[0] - first[0], look[1] - first[1]) || 1
        const ux = (look[0] - first[0]) / dl, uy = (look[1] - first[1]) / dl
        const ov = 0.9 + rnd() * 1.0
        push(sx, sy, false)
        push(sx + ux * ov * 0.5 - uy * 0.2, sy + uy * ov * 0.5 + ux * 0.2, false)
        push(sx + ux * ov - uy * 0.45, sy + uy * ov + ux * 0.45, false)
        s.closed = true
      }
    }
  }
  for (const s of subs) if (!s.shape) s.shape = s.pts.length
  return subs
}

export function polygonsOf(d: string, o: ParseOpts = {}): P2[][] {
  return parsePath(d, { step: 0.5, ...o }).filter((s) => s.pts.length > 2).map((s) => s.pts.slice(0, s.shape))
}

export interface Problem {
  level: 'error' | 'warn'
  code: string
  msg: string
  at?: string
}

export interface PathCheck {
  errors: string[]
  warnings: string[]
  bbox: [number, number, number, number] | null
  strokes: number
}

const nf = (s: string): number => Number.parseFloat(s)

export function checkPath(d: string): PathCheck {
  const errors: string[] = []
  const warnings: string[] = []
  if (typeof d !== 'string' || !d.trim()) return { errors: ['empty path'], warnings, bbox: null, strokes: 0 }
  const { tok, bad } = tokenize(d)
  if (bad) errors.push(`illegal characters "${bad.slice(0, 12)}" (grammar: M L l Q C O E Z, numbers)`)
  let i = 0
  let open = false
  let count = 0
  let lastPoint = false
  const numsAfter = (): number => {
    let k = 0
    while (i + k < tok.length && !CMD.test(tok[i + k])) k++
    return k
  }
  if (tok.length && tok[0] !== 'M' && tok[0] !== 'O' && tok[0] !== 'E') errors.push(`path must start with M, O or E, not "${tok[0]}"`)
  let curLen = 0
  while (i < tok.length) {
    const c = tok[i++]
    if (!CMD.test(c)) {
      errors.push(`number "${c}" without a command`)
      continue
    }
    const k = numsAfter()
    const bump = (n: number): void => {
      i += n
    }
    switch (c) {
      case 'M':
        if (k < 2 || k % 2) errors.push(`M needs pairs of numbers (got ${k})`)
        open = true
        count++
        curLen = Math.floor(k / 2)
        bump(k)
        break
      case 'L':
        if (!open) errors.push('L before M')
        if (k < 2 || k % 2) errors.push(`L needs pairs of numbers (got ${k})`)
        curLen += Math.floor(k / 2)
        bump(k)
        break
      case 'l':
        if (!open) errors.push('l before M')
        if (k < 2 || k % 2) errors.push(`l needs pairs of numbers (got ${k})`)
        curLen += Math.floor(k / 2)
        bump(k)
        break
      case 'Q':
        if (!open) errors.push('Q before M')
        if (k < 4 || k % 4) errors.push(`Q needs groups of 4 numbers (got ${k})`)
        curLen += Math.floor(k / 4)
        bump(k)
        break
      case 'C':
        if (!open) errors.push('C before M')
        if (k < 6 || k % 6) errors.push(`C needs groups of 6 numbers (got ${k})`)
        curLen += Math.floor(k / 6)
        bump(k)
        break
      case 'O':
        if (k !== 3 && k !== 4) errors.push(`O needs cx cy rx [ry] (got ${k} numbers)`)
        else if (nf(tok[i + 2]) <= 0 || (k === 4 && nf(tok[i + 3]) <= 0)) errors.push('O radii must be positive')
        open = false
        count++
        bump(k)
        break
      case 'E':
        if (k !== 6) errors.push(`E needs cx cy rx ry a0 a1 (got ${k} numbers)`)
        else if (nf(tok[i + 2]) <= 0 || nf(tok[i + 3]) <= 0) errors.push('E radii must be positive')
        if (!open) count++
        open = true
        bump(k)
        break
      case 'Z':
        if (!open || curLen < 3) errors.push('Z closes a stroke of at least 3 points')
        if (k) errors.push('Z takes no numbers')
        open = false
        break
    }
    lastPoint = true
  }
  void lastPoint
  if (!errors.length) {
    const subs = parsePath(d)
    for (const s of subs) {
      if (s.closed || s.pts.length < 4) continue
      const a = s.pts[0], b = s.pts[s.pts.length - 1]
      if (Math.hypot(a[0] - b[0], a[1] - b[1]) < 0.35) warnings.push('the stroke ends exactly where it began: close it with Z (the pen overshoots) or stop short')
    }
    const nums = tok.filter((t) => !CMD.test(t))
    const dec = nums.filter((t) => /\.\d{3,}/.test(t)).length
    if (dec) warnings.push(`${dec} coordinates have 3+ decimals (write one decimal: the engine adds the wobble)`)
    if (nums.length >= 8 && nums.filter((t) => /^-?\d+$/.test(t)).length / nums.length > 0.7) warnings.push('most coordinates are whole numbers: a tidy grid reads as computer-drawn (use 12.2, 11.8...)')
  }
  let bbox: PathCheck['bbox'] = null
  if (!errors.length) {
    for (const s of parsePath(d, { step: 0.4 })) {
      for (let k = 0; k < s.shape; k++) {
        const p = s.pts[k]
        bbox = bbox ? [Math.min(bbox[0], p[0]), Math.min(bbox[1], p[1]), Math.max(bbox[2], p[0]), Math.max(bbox[3], p[1])] : [p[0], p[1], p[0], p[1]]
      }
    }
  }
  return { errors, warnings, bbox, strokes: count }
}

const COLOUR_BASE = new Set([
  'ink', 'ink-soft', 'ink-you', 'pencil', 'pencil-mark', 'red', 'green', 'marker', 'hi', 'focus',
  'paper', 'paper-shade', 'slip', 'card', 'graph', 'kraft', 'check', 'photo', 'desk', 'desk-deep', 'rule-blue', 'rule-red', 'pad', 'pad-rule', 'check-rule',
  'ink-muted', 'pencil-text', 'orange-text', 'hi-deep', 'tape', 'tape-edge',
  'tomato', 'tangerine', 'lemon', 'grass', 'teal', 'sky', 'grape', 'bubblegum',
  'sticky-yellow', 'sticky-green', 'sticky-orange', 'sticky-pink', 'sticky-blue', 'current',
])
export function isArtColour(c: unknown): boolean {
  if (typeof c !== 'string') return false
  if (c === 'acc' || c === 'sil') return true
  const base = c.endsWith('~') ? c.slice(0, -1) : c
  return COLOUR_BASE.has(base) && base !== 'current'
}

export const ACCENT_KEYS = ['tomato', 'tangerine', 'lemon', 'grass', 'teal', 'sky', 'grape', 'bubblegum'] as const

export const USABLE: Partial<Record<ArtKind, [number, number, number, number]>> = {
  icon: [2, 2, 22, 22],
  doodle: [4, 4, 60, 60],
  sticker: [6, 6, 58, 58],
  mascot: [4, 3, 60, 70],
}

export const BUDGET: Record<'icon' | 'doodle' | 'sticker' | 'mascot', { parts: number; small: number; micro: number; hi: number }> = {
  icon: { parts: 6, small: 4, micro: 3, hi: 6 },
  doodle: { parts: 14, small: 9, micro: 5, hi: 8 },
  sticker: { parts: 24, small: 16, micro: 8, hi: 10 },
  mascot: { parts: 34, small: 22, micro: 12, hi: 12 },
}

export function kindOfDef(def: { kind?: ArtKind; grid: ArtDef['grid'] }): ArtKind {
  if (def.kind) return def.kind
  if (def.grid === 24) return 'icon'
  if (Array.isArray(def.grid)) return 'mascot'
  return 'doodle'
}

const PART_TAGS = new Set(['f', 's', 'c', 'd', 'h', 't'])

function widthOf(p: Part): number | undefined {
  if (p[0] === 's') return p[2]
  if (p[0] === 'c') return p[3]
  if (p[0] === 'h') return undefined
  return undefined
}

export type GlyphLookup = (font: string, ch: string) => boolean | undefined

export function validateParts(parts: readonly Part[], kind: ArtKind, tier: string, hasAccent: boolean, glyph?: GlyphLookup): Problem[] {
  const out: Problem[] = []
  const area = USABLE[kind]
  const E = (code: string, msg: string, at: string): number => out.push({ level: 'error', code, msg, at })
  const W = (code: string, msg: string, at: string): number => out.push({ level: 'warn', code, msg, at })
  parts.forEach((p, idx) => {
    const at = `${tier}[${idx}]`
    if (!Array.isArray(p) || !PART_TAGS.has(p[0] as string)) return void E('part-shape', `unknown part ${JSON.stringify(p)?.slice(0, 40)}`, at)
    const paths: string[] = []
    switch (p[0]) {
      case 'f':
        if (!isArtColour(p[1])) E('colour', `"${String(p[1])}" is not an allowed color (PaintKey, key~, acc, sil)`, at)
        if (p[1] === 'acc' && !hasAccent && kind === 'icon') W('accent', "'acc' part but the def has no `accent` (falls back to the highlighter)", at)
        paths.push(p[2])
        if (p[3] !== undefined && !(p[3] >= 0 && p[3] <= 3)) E('mis', 'fill misregistration multiplier must be 0..3', at)
        break
      case 's':
        paths.push(p[1])
        break
      case 'c':
        if (!isArtColour(p[1]) || p[1] === 'sil') E('colour', `"${String(p[1])}" is not an allowed stroke color`, at)
        paths.push(p[2])
        break
      case 'h':
        paths.push(p[1])
        break
      case 'd': {
        const [, x, y, r] = p
        if (![x, y].every((v) => typeof v === 'number' && Number.isFinite(v))) E('part-shape', 'dot needs numeric x y', at)
        else if (area && (x < area[0] || x > area[2] || y < area[1] || y > area[3])) E('bounds', `dot (${x}, ${y}) is outside the usable area ${area[0]},${area[1]}..${area[2]},${area[3]}`, at)
        if (r !== undefined && !(r >= 0.6 && r <= (tier === 'micro' ? 8 : 6))) W('dot-radius', `dot radius ${r} is outside 0.6..${tier === 'micro' ? 8 : 6} grid units`, at)
        return
      }
      case 't': {
        const [, txt, x, y, size] = p
        const font = p[6] ?? 'hand'
        if (font !== 'hand' && font !== 'type') E('text', `unknown lettering font "${String(font)}" (hand | type)`, at)
        else if (glyph) for (const ch of String(txt).toUpperCase()) if (ch !== ' ' && glyph(font, ch) === false) E('text', `no glyph for "${ch}" in the ${font} lettering`, at)
        if (![x, y, size].every((v) => typeof v === 'number' && Number.isFinite(v))) E('part-shape', 'text needs numeric x y size', at)
        if (p[5] !== undefined && !isArtColour(p[5])) E('colour', `"${String(p[5])}" is not an allowed color`, at)
        return
      }
    }
    const wm = widthOf(p)
    if (wm !== undefined) {
      const lo = kind === 'icon' && tier !== 'hi' ? 0.6 : 0.45
      const hi = tier === 'micro' ? 1.8 : kind === 'icon' ? 1.4 : 1.5
      if (!(wm >= 0.4 && wm <= 1.8)) E('width', `widthMul ${wm} is outside 0.4..1.8`, at)
      else if (wm < lo || wm > hi) W('width', `widthMul ${wm} is outside ${lo}..${hi} for ${kind} ${tier}`, at)
    }
    for (const d of paths) {
      const r = checkPath(d)
      for (const m of r.errors) E('path', m, at)
      for (const m of r.warnings) W('path-style', m, at)
      if (!r.errors.length && r.bbox && area && !(p[0] === 'f' && p[1] === 'sil')) {
        const [x0, y0, x1, y1] = r.bbox
        const slack = 0.5
        if (x0 < area[0] - slack || y0 < area[1] - slack || x1 > area[2] + slack || y1 > area[3] + slack) {
          E('bounds', `path extent ${x0.toFixed(1)},${y0.toFixed(1)}..${x1.toFixed(1)},${y1.toFixed(1)} leaves the usable area ${area[0]},${area[1]}..${area[2]},${area[3]}`, at)
        }
      }
    }
  })
  return out
}

export function validateArt(def: ArtDef, o: { id?: string; kind?: ArtKind; glyph?: GlyphLookup } = {}): Problem[] {
  const out: Problem[] = []
  const kind = o.kind ?? kindOfDef(def)
  const g = def.grid
  const okGrid = g === 24 || g === 64 || (Array.isArray(g) && g.length === 2 && g.every((v) => Number.isFinite(v) && v >= 8 && v <= 512))
  if (!okGrid) out.push({ level: 'error', code: 'grid', msg: `grid must be 24, 64 or [w, h] (got ${JSON.stringify(g)})` })
  if (!Array.isArray(def.parts) || !def.parts.length) out.push({ level: 'error', code: 'parts', msg: 'a definition needs at least one part' })
  if (def.accent !== undefined && !([...ACCENT_KEYS, 'hi', 'kraft'] as string[]).includes(def.accent)) out.push({ level: 'error', code: 'accent', msg: `accent "${String(def.accent)}" is not a stationery accent, "hi" or "kraft"` })
  if (def.nibK !== undefined && !(def.nibK >= 0.02 && def.nibK <= 0.14)) out.push({ level: 'error', code: 'nibK', msg: 'nibK must be 0.02..0.14' })
  if (def.tags !== undefined && (!Array.isArray(def.tags) || def.tags.some((t) => typeof t !== 'string' || !t))) out.push({ level: 'error', code: 'tags', msg: 'tags must be non-empty strings' })
  const b = BUDGET[kind as keyof typeof BUDGET]
  const tiers: Array<['parts' | 'small' | 'micro' | 'hi', readonly Part[] | undefined]> = [['parts', def.parts], ['small', def.small], ['micro', def.micro], ['hi', def.hi]]
  for (const [name, list] of tiers) {
    if (!list) continue
    if (!Array.isArray(list)) {
      out.push({ level: 'error', code: 'parts', msg: `${name} must be an array of parts` })
      continue
    }
    out.push(...validateParts(list, kind, name, def.accent !== undefined, o.glyph))
    const blots = list.filter((p) => p[0] === 'd').length
    const drawn = list.length - blots
    if (b && drawn > b[name]) out.push({ level: 'error', code: 'budget', msg: `${name} has ${drawn} fills / strokes; the ${kind} budget is ${b[name]} (put several strokes in one path with M)`, at: name })
    if (blots > 8) out.push({ level: 'error', code: 'budget', msg: `${name} has ${blots} blots; at most 8`, at: name })
  }
  if (def.small && def.parts && JSON.stringify(def.small) === JSON.stringify(def.parts)) out.push({ level: 'warn', code: 'small-copy', msg: '`small` is identical to the master: redraw it (bigger silhouette, fewer details, heavier strokes)' })
  return out
}

import { PathWriter } from '@/lib/ink/geom'
import type { Q } from '@/lib/ink/paint'
import type { Rng } from '@/lib/ink/rng'
import { GLYPH_FONTS, type GlyphFont } from '@/lib/ink/art/glyphs'
import type { LetterFont } from '@/lib/ink/art/types'

type Cmd = readonly [string, ...number[]]
const parsed = new Map<string, Cmd[]>()

function commands(font: LetterFont, ch: string): Cmd[] {
  const key = font + ch
  let c = parsed.get(key)
  if (c) return c
  c = []
  const d = GLYPH_FONTS[font].d[ch] ?? ''
  for (const m of d.matchAll(/([MLQZ])([^MLQZ]*)/g)) {
    const nums = m[2].trim() ? m[2].trim().split(/[ ,]+/).map(Number) : []
    c.push([m[1], ...nums] as unknown as Cmd)
  }
  parsed.set(key, c)
  return c
}

const upper = (s: string): string => s.toUpperCase()

const FIT = 0.8

export const hasGlyph = (font: string, ch: string): boolean => {
  const F = (GLYPH_FONTS as Record<string, GlyphFont>)[font]
  return !!F && (ch === ' ' || !!F.d[ch])
}

export function measureText(font: LetterFont, text: string, size: number, spacing = 0): number {
  const F = GLYPH_FONTS[font]
  let w = 0
  const t = upper(text)
  for (let i = 0; i < t.length; i++) w += ((F.adv[t[i]] ?? F.adv[' '] ?? 300) / 1000) * size * FIT + (i < t.length - 1 ? spacing : 0)
  return w
}

export const capHeight = (font: LetterFont, size: number): number => (GLYPH_FONTS[font].cap / 1000) * size * FIT

export interface TextOpts {
  font?: LetterFont
  anchor?: 'start' | 'middle' | 'end'
  spacing?: number
  jitter?: number
  rot?: number
  squeeze?: number
  q?: Q
}

export interface TextPath {
  d: string
  width: number
  bbox: [number, number, number, number]
}

export function textPath(text: string, x: number, y: number, em: number, rng: Rng, o: TextOpts = {}): TextPath {
  const font = o.font ?? 'hand'
  const F = GLYPH_FONTS[font]
  const t = upper(text)
  const sq = o.squeeze ?? 1
  const size = em * FIT
  const s = size / 1000
  const spacing = o.spacing ?? 0
  const jit = (o.jitter ?? 0) * 0.3
  const total = measureText(font, t, em, spacing) * sq
  const x0 = o.anchor === 'start' ? x : o.anchor === 'end' ? x - total : x - total / 2
  const w = new PathWriter(o.q ?? 10)
  const ampY = 0.045 * size * jit
  const ph = rng() * 6.28, ph2 = rng() * 6.28
  const rot0 = ((o.rot ?? 0) * Math.PI) / 180
  const cr = Math.cos(rot0), sr = Math.sin(rot0)
  let pen = 0
  const bb: [number, number, number, number] = [Infinity, Infinity, -Infinity, -Infinity]
  for (let i = 0; i < t.length; i++) {
    const ch = t[i]
    const adv = ((F.adv[ch] ?? F.adv[' '] ?? 300) / 1000) * size * sq
    const cmds = commands(font, ch)
    if (cmds.length) {
      const dy = ampY * (0.6 * Math.sin(i * 0.9 + ph) + 0.4 * Math.sin(i * 2.3 + ph2)) + rng.gauss(0, ampY * 0.3)
      const lean = (rng.gauss(0, 1.5) * jit * Math.PI) / 180
      const gx = pen + adv / 2, gy = 0
      const cl = Math.cos(lean), sl = Math.sin(lean)
      const tr = (px: number, py: number): [number, number] => {
        let X = px * s * sq + pen, Y = py * s + dy
        const rx = X - gx, ry = Y - gy
        X = gx + rx * cl - ry * sl
        Y = gy + rx * sl + ry * cl
        const ax = x0 - x + X
        return [x + ax * cr - Y * sr, y + ax * sr + Y * cr]
      }
      for (const c of cmds) {
        const k = c[0]
        if (k === 'M') { const [a, b] = tr(c[1], c[2]); w.M(a, b); grow(bb, a, b) }
        else if (k === 'L') { const [a, b] = tr(c[1], c[2]); w.L(a, b); grow(bb, a, b) }
        else if (k === 'Q') { const [a, b] = tr(c[1], c[2]); const [e, f] = tr(c[3], c[4]); w.Q(a, b, e, f); grow(bb, e, f) }
        else if (k === 'Z') w.Z()
      }
    }
    pen += adv + spacing
  }
  return { d: w.d, width: total, bbox: bb[0] === Infinity ? [x, y, x, y] : bb }
}

function grow(b: [number, number, number, number], x: number, y: number): void {
  if (x < b[0]) b[0] = x
  if (y < b[1]) b[1] = y
  if (x > b[2]) b[2] = x
  if (y > b[3]) b[3] = y
}

import { dieCut, type DieCutResult } from '@/lib/ink/art-draw'
import type { ArtDef } from '@/lib/ink/art/types'
import { clamp } from '@/lib/ink/rng'

export interface MascotDrawOpts {
  tier?: 'lo' | 'hi'
  idPrefix?: string
  border?: number
  shadow?: boolean
}

export const mascotVariant = (size: number): 'micro' | 'small' | 'master' | 'hi' => (size < 28 ? 'micro' : size < 56 ? 'small' : size < 140 ? 'master' : 'hi')

export function drawMascot(def: ArtDef, size: number, seed: string | number, o: MascotDrawOpts = {}): DieCutResult {
  const px = Math.max(16, Math.round(size))
  const border = o.border ?? (px < 28 ? 1 : clamp(px * 0.065, 1.8, 6.5))
  const art = Math.max(8, px - 2 * Math.ceil(border + 2))
  const nib = clamp(art * (def.nibK ?? 0.05), 1.05, 4.6)
  return dieCut(def, art, seed, { border, nib, tier: o.tier ?? 'lo', variant: mascotVariant(px), idPrefix: o.idPrefix, shadow: o.shadow, silAll: false, crisp: true, grain: false })
}

import { Ink, type InkResult } from '@/lib/ink/builder'
import { area, densifyClosed, ellipsePoly, polyPath, roundRectPoly } from '@/lib/ink/geom'
import type { PaintKey } from '@/lib/ink/paint'
import { clamp, type Rng } from '@/lib/ink/rng'
import type { Pt } from '@/lib/ink/types'
import { measureText, textPath } from '@/lib/ink/art/glyph-text'
import type { StampGen } from '@/lib/ink/art/types'

export interface StampOpts extends Partial<Omit<StampGen, 'gen' | 'text' | 'shape' | 'kind'>> {
  seed?: string | number
  grain?: boolean
}

const INK: Record<NonNullable<StampGen['ink']>, PaintKey> = { red: 'red', 'ink-you': 'ink-you', green: 'green', ink: 'ink' }

const flip = (pts: Pt[]): Pt[] => (area(pts) > 0 ? pts.slice().reverse() : pts)

function ring(outer: Pt[], inner: Pt[]): string {
  const o = area(outer) < 0 ? outer.slice().reverse() : outer
  const i = area(inner) > 0 ? inner.slice().reverse() : inner
  return polyPath(o, 10) + polyPath(i, 10)
}

function star(cx: number, cy: number, ro: number, ri: number, rot = -90): Pt[] {
  const p: Pt[] = []
  for (let i = 0; i < 10; i++) {
    const a = ((rot + i * 36) * Math.PI) / 180
    const r = i % 2 ? ri : ro
    p.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r])
  }
  return p
}

function dashes(poly: Pt[], len: number, gap: number, w: number, rng: Rng): string {
  let d = ''
  const m = poly.length
  let carry = 0
  let on = true
  let left = len
  for (let i = 0; i < m; i++) {
    const a = poly[i], b = poly[(i + 1) % m]
    const L = Math.hypot(b[0] - a[0], b[1] - a[1])
    const ux = (b[0] - a[0]) / (L || 1), uy = (b[1] - a[1]) / (L || 1)
    let s = carry
    while (s < L) {
      const step = Math.min(left, L - s)
      if (on && step > 0.5) {
        const p0: Pt = [a[0] + ux * s, a[1] + uy * s], p1: Pt = [a[0] + ux * (s + step), a[1] + uy * (s + step)]
        const nx = -uy * w * 0.5, ny = ux * w * 0.5
        d += polyPath([[p0[0] + nx, p0[1] + ny], [p1[0] + nx, p1[1] + ny], [p1[0] - nx, p1[1] - ny], [p0[0] - nx, p0[1] - ny]], 10)
      }
      s += step
      left -= step
      if (left <= 0.01) {
        on = !on
        left = (on ? len : gap) * (0.85 + rng() * 0.3)
      }
    }
    carry = 0
  }
  return d
}

function cleanRect(x: number, y: number, w: number, h: number, r: number): Pt[] {
  return densifyClosed(roundRectPoly(x, y, w, h, r, 5), 5)
}

export function stamp(text: string, shape: StampGen['shape'], o: StampOpts = {}): InkResult {
  const key = INK[o.ink ?? 'red']
  const seed = `stamp:${o.seed ?? text}:${shape}`
  const ink = new Ink(seed, { tier: 'lo', grain: o.grain })
  const rng = ink.rng.fork('stamp')
  const round = shape === 'round' || shape === 'burst'
  const W = o.w ?? (round ? 96 : shape === 'void' ? 160 : 160)
  const H = o.h ?? (round ? W : shape === 'void' ? 64 : 56)
  const tilt = o.tilt ?? (rng.range(-5, 5))
  const cx = W / 2, cy = H / 2
  const TXT = text.toUpperCase()

  const impression = (r: Rng, alpha: number): void => {
    let d = ''
    const outerW = clamp(H * 0.045, 2, 3), innerW = 1.1
    if (shape === 'rect') {
      const a = cleanRect(0, 0, W, H, 5)
      const b = cleanRect(outerW, outerW, W - 2 * outerW, H - 2 * outerW, 3.4)
      d += ring(a, b)
      const gap = 3.1
      const c = cleanRect(outerW + gap, outerW + gap, W - 2 * (outerW + gap), H - 2 * (outerW + gap), 2.4)
      const e = cleanRect(outerW + gap + innerW, outerW + gap + innerW, W - 2 * (outerW + gap + innerW), H - 2 * (outerW + gap + innerW), 2)
      d += o.dashed ? dashes(c, 5.5, 3.2, innerW + 0.3, r.fork('dash')) : ring(c, e)
      const innerH = H - 2 * (outerW + gap + innerW)
      const innerW2 = W - 2 * (outerW + gap + innerW) - 10
      const sub = o.sub
      let em = Math.min(innerH * (sub ? 0.5 : 0.62), 38)
      const spacing = clamp(em * 0.08, 1, 3.4)
      const fit = innerW2 / Math.max(1, measureText('type', TXT, 1, 0) + (TXT.length - 1) * (spacing / em))
      em = Math.min(em, fit)
      const cap = 0.68 * em
      const ty = sub ? cy - innerH * 0.06 + cap / 2 - 1 : cy + cap / 2
      const t = textPath(TXT, cx, ty, em, r.fork('t'), { font: 'type', spacing: (spacing * em) / Math.max(em, 1) * 0.9, jitter: 0.25 })
      d += t.d
      if (sub) {
        const sm = clamp(innerH * 0.2, 6, 10)
        const st = textPath(sub.toUpperCase(), cx, cy + innerH * 0.34, sm, r.fork('s'), { font: 'type', spacing: 1.2, jitter: 0.2 })
        d += st.d
      }
    } else if (shape === 'round' || shape === 'burst') {
      const R = W / 2
      if (shape === 'burst') {
        const pts: Pt[] = []
        for (let i = 0; i < 24; i++) {
          const a = (i / 24) * Math.PI * 2 - Math.PI / 2
          const rr = i % 2 ? R * 0.82 : R - 1
          pts.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr])
        }
        d += ring(pts, densifyClosed(ellipsePoly(cx, cy, R * 0.76, R * 0.76, 48), 4))
        d += ring(densifyClosed(ellipsePoly(cx, cy, R * 0.66, R * 0.66, 48), 4), densifyClosed(ellipsePoly(cx, cy, R * 0.66 - 1.1, R * 0.66 - 1.1, 48), 4))
      } else {
        const a = densifyClosed(ellipsePoly(cx, cy, R - 0.5, R - 0.5, 60), 5)
        const b = densifyClosed(ellipsePoly(cx, cy, R - 0.5 - 2.6, R - 0.5 - 2.6, 60), 5)
        d += ring(a, b)
        const rin = R * 0.63
        d += ring(densifyClosed(ellipsePoly(cx, cy, rin, rin, 48), 4), densifyClosed(ellipsePoly(cx, cy, rin - 1.1, rin - 1.1, 48), 4))
      }
      const inner = shape === 'burst' ? R * 0.6 : R * 0.62
      let em = Math.min(W * 0.3, 40)
      const fit = (inner * 1.78) / Math.max(0.5, measureText('type', TXT, 1, 0) + TXT.length * 0.06)
      em = Math.min(em, fit)
      const cap = 0.68 * em
      const t = textPath(TXT, cx, cy + cap / 2 - (o.sub ? 1.5 : 0), em, r.fork('t'), { font: 'type', spacing: em * 0.06, jitter: 0.25 })
      d += t.d
      if (o.sub) d += textPath(o.sub.toUpperCase(), cx, cy + cap / 2 + em * 0.42, Math.max(5.5, em * 0.28), r.fork('s'), { font: 'type', spacing: 0.8, jitter: 0.2 }).d
      const ns = o.stars ?? (shape === 'round' ? 2 : 0)
      for (let i = 0; i < ns; i++) {
        const sx = cx + (i === 0 ? -1 : 1) * inner * 0.68
        d += polyPath(star(sx, cy - cap * 1.05 - 3, 2.6, 1.1, -90), 10)
      }
      if (shape === 'round') {
        const rim = o.ring ?? ''
        const chars = Array.from(rim.toUpperCase())
        if (chars.length) {
          const rr = R - 2.6 - 3.4 - 2
          const span = chars.length >= 12 ? 300 : chars.length * 26
          const sz = clamp((rr * ((span * Math.PI) / 180)) / (chars.length * 0.86), 5.2, 10)
          chars.forEach((ch, i) => {
            if (ch === ' ') return
            const ang = -90 - span / 2 + ((i + 0.5) / chars.length) * span
            const A = (ang * Math.PI) / 180
            d += textPath(ch, cx + Math.cos(A) * rr, cy + Math.sin(A) * rr, sz, r.fork(`ch${i}`), { font: 'type', rot: ang + 90, jitter: 0.1 }).d
          })
        }
      }
    } else {
      const em = Math.min(H * 0.86, (W * 0.86) / Math.max(1, measureText('type', TXT, 1, 0)))
      const t = textPath(TXT, cx, cy + em * 0.34, em, r.fork('t'), { font: 'type', spacing: em * 0.04, jitter: 0.35, rot: -8 })
      d += t.d
      const bar = densifyClosed([[cx - W * 0.44, cy + 3.5], [cx + W * 0.44, cy - 3.2], [cx + W * 0.44, cy - 0.2], [cx - W * 0.44, cy + 6.4]], 5)
      d += polyPath(flip(bar), 10)
    }
    ink.flat('text', d, key, alpha, { bbox: [-6, -6, W + 6, H + 6] })
  }

  ink.group({ transform: `rotate(${(tilt).toFixed(2)} ${cx.toFixed(1)} ${cy.toFixed(1)})` }, () => {
    if (o.ghost) ink.group({ transform: `translate(${(1.6).toFixed(1)} ${(-1.3).toFixed(1)}) rotate(0.8 ${cx.toFixed(1)} ${cy.toFixed(1)})` }, () => impression(rng.fork('ghost'), 0.2), 'stamp')
    impression(rng.fork('main'), 0.92)
  }, 'stamp')
  return ink.toSvg({ w: W, h: H, pad: 10 })
}

import type { PaintKey } from '@/lib/ink/paint'
import type { Accent } from '@/lib/ink/types'
import { validateArt, type Problem } from '@/lib/ink/art/dsl'

export type ArtKind = 'icon' | 'doodle' | 'sticker' | 'mascot' | 'prop' | 'scene'

export type ArtColour = Exclude<PaintKey, 'current'> | `${Exclude<PaintKey, 'current'>}~` | 'acc' | 'sil'

export type LetterFont = 'hand' | 'type'

export interface Hand {
  start?: 'pool' | 'soft'
  end?: 'pool' | 'flick' | 'soft'
  taper?: number
}

export type Part =
  | readonly ['f', ArtColour, string, number?]
  | readonly ['s', string, number?, Hand?]
  | readonly ['c', ArtColour, string, number?, Hand?]
  | readonly ['d', number, number, number?]
  | readonly ['h', string, number?]
  | readonly ['t', string, number, number, number, ArtColour?, LetterFont?]

export type ArtAccent = Accent | 'hi' | 'kraft'

export interface ArtDef {
  grid: 24 | 64 | readonly [number, number]
  parts: readonly Part[]
  small?: readonly Part[]
  micro?: readonly Part[]
  hi?: readonly Part[]
  accent?: ArtAccent
  nibK?: number
  tags?: readonly string[]
  shade?: boolean
  tilt?: number
  rtl?: 'flip'
  mirror?: boolean
  kind?: ArtKind
}

export interface BadgeGen {
  gen: 'badge'
  text: string
  shape?: 'scallop' | 'starburst' | 'rosette' | 'banner' | 'tag' | 'ticket' | 'plate' | 'shield' | 'medal'
  color?: Exclude<PaintKey, 'current'>
  sub?: string
  bumps?: number
  amp?: number
  deco?: 'tick' | 'star' | 'sparkle' | 'swoosh' | 'percent'
  textColor?: Exclude<PaintKey, 'current'>
  tilt?: number
  tags?: readonly string[]
  kind?: ArtKind
}

export interface StampGen {
  gen: 'stamp'
  text: string
  shape: 'rect' | 'round' | 'burst' | 'void'
  sub?: string
  ring?: string
  ink?: 'red' | 'ink-you' | 'green' | 'ink'
  w?: number
  h?: number
  tilt?: number
  ghost?: boolean
  dashed?: boolean
  wear?: number
  stars?: number
  tags?: readonly string[]
  kind?: ArtKind
}

export type StickerDef = ArtDef | BadgeGen | StampGen

declare const process: { env?: { NODE_ENV?: string } } | undefined

const isDev = (): boolean => {
  const env = (import.meta as unknown as { env?: { DEV?: boolean } }).env
  if (env && typeof env.DEV === 'boolean') return env.DEV
  return typeof process !== 'undefined' && process?.env?.NODE_ENV !== 'production'
}

function check(kind: ArtKind, id: string, def: ArtDef): void {
  if (!isDev()) return
  const errors = validateArt(def, { id, kind }).filter((p: Problem) => p.level === 'error')
  if (errors.length) console.error(`ink art: ${kind} "${id}": ${errors.map((e) => `${e.at ? e.at + ' ' : ''}${e.msg}`).join('; ')}`)
}

function make<T extends Record<string, ArtDef>>(kind: ArtKind, map: T): T {
  const out: Record<string, ArtDef> = {}
  for (const id of Object.keys(map)) {
    const def = { ...map[id], kind }
    check(kind, id, def)
    out[id] = def
  }
  return out as T
}

export const defineIcons = <const T extends Record<string, ArtDef>>(map: T): T => make('icon', map)
export const defineDoodles = <const T extends Record<string, ArtDef>>(map: T): T => make('doodle', map)
export const defineMascot = <const T extends Record<string, ArtDef>>(map: T): T => make('mascot', map)
export const defineProps = <const T extends Record<string, ArtDef>>(map: T): T => make('prop', map)
export function defineStickers<const T extends Record<string, StickerDef>>(map: T): T {
  const out: Record<string, StickerDef> = {}
  for (const id of Object.keys(map)) {
    const def = map[id]
    if ('gen' in def) out[id] = { ...def, kind: 'sticker' }
    else {
      const d = { ...def, kind: 'sticker' as const }
      check('sticker', id, d)
      out[id] = d
    }
  }
  return out as T
}

export const defineIcon = (def: ArtDef): ArtDef => make('icon', { def }).def
export const defineDoodle = (def: ArtDef): ArtDef => make('doodle', { def }).def
export const defineSticker = (def: StickerDef): StickerDef => defineStickers({ def }).def

export const isGen = (d: StickerDef): d is BadgeGen | StampGen => 'gen' in d

import { Ink, type InkResult, type Knobs } from '@/lib/ink/builder'
import { flatFill } from '@/lib/ink/fills'
import { PathWriter, TIERS, smoothClosed } from '@/lib/ink/geom'
import { noise1 } from '@/lib/ink/noise'
import { n, type PaintKey } from '@/lib/ink/paint'
import { pen as penSpec } from '@/lib/ink/pens'
import { clamp, hashSeed, type Rng } from '@/lib/ink/rng'
import type { BBox, Pt, Tier } from '@/lib/ink/types'
import { parsePath, polygonsOf, kindOfDef, type Sub } from '@/lib/ink/art/dsl'
import { capHeight, textPath } from '@/lib/ink/art/glyph-text'
import { isGen, type ArtAccent, type ArtColour, type ArtDef, type ArtKind, type Hand, type Part, type StickerDef } from '@/lib/ink/art/types'

import { badgeSkeleton } from '@/lib/ink/art/badge-gen'
import { stamp } from '@/lib/ink/art/rubber-stamp'
export { badgeSkeleton }
export type { BadgeOpts } from '@/lib/ink/art/badge-gen'
export { stamp }
export type { StampOpts } from '@/lib/ink/art/rubber-stamp'
export { measureText, textPath } from '@/lib/ink/art/glyph-text'
export type { ArtDef, ArtKind, Part } from '@/lib/ink/art/types'

export type Variant = 'micro' | 'small' | 'master' | 'hi'

export function variantFor(kind: ArtKind, size: number): Variant {
  switch (kind) {
    case 'icon':
      return size <= 13 ? 'micro' : size <= 19 ? 'small' : size <= 40 ? 'master' : 'hi'
    case 'doodle':
      return size < 72 ? 'small' : size < 120 ? 'master' : 'hi'
    case 'sticker':
      return size < 80 ? 'small' : size < 120 ? 'master' : 'hi'
    case 'mascot':
      return size < 40 ? 'micro' : size < 72 ? 'small' : size < 140 ? 'master' : 'hi'
    default:
      return 'master'
  }
}

export function partsFor(def: ArtDef, variant: Variant): readonly Part[] {
  if (variant === 'micro') return def.micro ?? def.small ?? def.parts
  if (variant === 'small') return def.small ?? def.parts
  if (variant === 'hi' && def.hi) return [...def.parts, ...def.hi]
  return def.parts
}

const NIB: Record<ArtKind, { k: number; min: number; max: number }> = {
  icon: { k: 0.068, min: 1.45, max: 3.4 },
  doodle: { k: 0.05, min: 1.7, max: 5.2 },
  sticker: { k: 0.055, min: 1.8, max: 5.2 },
  mascot: { k: 0.05, min: 1.6, max: 5 },
  prop: { k: 0.05, min: 1.6, max: 5 },
  scene: { k: 0.04, min: 1.4, max: 4 },
}

export interface DrawOpts {
  tone?: 'ui' | 'doodle'
  tier?: Tier
  ink?: PaintKey
  accent?: ArtAccent
  kind?: ArtKind
  variant?: Variant
  nib?: number
  shade?: boolean
  grain?: boolean
  crisp?: boolean
  calm?: boolean
  knobs?: Partial<Knobs>
  silAll?: boolean
  pad?: number
}

export interface Silhouette {
  fills: string[]
  lines: string[]
  pts: Pt[]
  W: number
}

export interface SkeletonResult extends InkResult {
  variant: Variant
  kind: ArtKind
  nib: number
  k: number
  silhouette: Silhouette
}

function wander(pts: Pt[], rng: Rng, k: number, amp: number): Pt[] {
  let L = 20
  for (let i = 1; i < pts.length; i++) L += Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]) * k
  const nx = noise1(rng.fork('x'), L, 7 * k), ny = noise1(rng.fork('y'), L, 7 * k)
  const ox = rng.gauss(0, amp * 0.6), oy = rng.gauss(0, amp * 0.6)
  let s = 0
  return pts.map(([x, y], i) => {
    if (i) s += Math.hypot(x - pts[i - 1][0], y - pts[i - 1][1]) * k
    return [x * k + ox + nx(s) * amp, y * k + oy + ny(s) * amp]
  })
}

function roundCorners(pts: Pt[], anchor: boolean[], r: number): Pt[] {
  if (pts.length < 3 || r < 0.2) return pts
  const out: Pt[] = [pts[0]]
  for (let i = 1; i < pts.length - 1; i++) {
    const a = pts[i - 1], b = pts[i], c = pts[i + 1]
    if (!anchor[i]) {
      out.push(b)
      continue
    }
    const l1 = Math.hypot(b[0] - a[0], b[1] - a[1]), l2 = Math.hypot(c[0] - b[0], c[1] - b[1])
    if (l1 < r * 1.6 || l2 < r * 1.6) {
      out.push(b)
      continue
    }
    const cos = ((b[0] - a[0]) * (c[0] - b[0]) + (b[1] - a[1]) * (c[1] - b[1])) / (l1 * l2)
    if (cos > 0.85) {
      out.push(b)
      continue
    }
    const rr = Math.min(r, l1 * 0.4, l2 * 0.4)
    const p1: Pt = [b[0] + ((a[0] - b[0]) / l1) * rr, b[1] + ((a[1] - b[1]) / l1) * rr]
    const p2: Pt = [b[0] + ((c[0] - b[0]) / l2) * rr, b[1] + ((c[1] - b[1]) / l2) * rr]
    for (let t = 0; t <= 4; t++) {
      const u = t / 4, v = 1 - u
      out.push([v * v * p1[0] + 2 * u * v * b[0] + u * u * p2[0], v * v * p1[1] + 2 * u * v * b[1] + u * u * p2[1]])
    }
  }
  out.push(pts[pts.length - 1])
  return out
}

const openPath = (pts: Pt[]): string => {
  const w = new PathWriter(10)
  pts.forEach((p, i) => (i ? w.L(p[0], p[1]) : w.M(p[0], p[1])))
  return w.d
}

const WASH_ALPHA = 0.42
const DARK: ReadonlySet<string> = new Set(['ink', 'ink-soft', 'ink-you', 'pencil', 'red', 'green', 'focus'])

export function paintSkeleton(ink: Ink, def: ArtDef, size: number, o: DrawOpts = {}, origin: Pt = [0, 0]): { silhouette: Silhouette; variant: Variant; kind: ArtKind; nib: number; k: number; w: number; h: number } {
  const kind = o.kind ?? kindOfDef(def)
  const variant = o.variant ?? variantFor(kind, size)
  const parts = partsFor(def, variant)
  const [gw, gh] = def.grid === 24 || def.grid === 64 ? [def.grid, def.grid] : def.grid
  const k = size / Math.max(gw, gh)
  const tone = o.tone ?? (kind === 'icon' ? 'ui' : 'doodle')
  const nibSpec = NIB[kind]
  const nib = o.nib ?? clamp(size * (def.nibK ?? nibSpec.k), nibSpec.min, nibSpec.max)
  const inkKey: PaintKey = o.ink ?? (tone === 'ui' ? 'current' : 'ink')
  const accent = (o.accent ?? def.accent ?? 'hi') as PaintKey
  const icon = kind === 'icon'
  const sticker = kind === 'sticker'
  const sPen = icon ? penSpec('ink.fine', { step: size <= 40 ? 0.7 : 1.2 }) : penSpec('ink')
  const penW = sPen.W
  const wob = 0.12
  const amp = clamp(size * 0.002, 0.04, 0.22)
  const root = ink.rng.fork('skel')
  const sil: Silhouette = { fills: [], lines: [], pts: [], W: nib }
  const seenFills = new Set<string>()
  let lastFill = ''
  const off = (ps: Pt[]): Pt[] => (origin[0] || origin[1] ? ps.map(([x, y]) => [x + origin[0], y + origin[1]] as Pt) : ps)
  const tc = Math.cos(((def.tilt ?? 0) * Math.PI) / 180), ts = Math.sin(((def.tilt ?? 0) * Math.PI) / 180)
  const turn = def.tilt
    ? (ps: Pt[]): Pt[] => ps.map(([x, y]) => [gw / 2 + (x - gw / 2) * tc - (y - gh) * ts, gh + (x - gw / 2) * ts + (y - gh) * tc] as Pt)
    : (ps: Pt[]): Pt[] => ps
  const fillAlpha = sticker ? 1 : icon ? 0.9 : 0.95
  const fillMaterial = sticker ? 'wash' : 'marker'
  const cornerR = nib * 0.55

  parts.forEach((p, i) => {
    const pr = root.fork('p' + i)
    const tag = p[0]
    if (tag === 'f') {
      const colour = p[1]
      const isSil = colour === 'sil'
      if (colour === 'acc' && tone === 'ui') return
      polygonsOf(p[2], { rnd: pr }).forEach((poly, pi) => {
        const px = off(wander(turn(poly), pr.fork('w' + pi), k, amp))
        sil.fills.push(smoothPath(px))
        for (let q = 0; q < px.length; q += 2) sil.pts.push(px[q])
        if (isSil) return
        const wash_ = colour === 'acc' || colour.endsWith('~')
        const key = (colour === 'acc' ? accent : wash_ ? colour.slice(0, -1) : colour) as PaintKey
        if (wash_) {
          flatFill(ink, px, key, WASH_ALPHA, 'marker')
        } else {
          const run = (): void => flatFill(ink, px, key, fillAlpha, sticker ? 'wash' : DARK.has(key) ? 'text' : fillMaterial)
          if (sticker && seenFills.has(key) && lastFill !== key) ink.group({}, run, 'wash')
          else run()
          seenFills.add(key)
          lastFill = key
        }
      })
    } else if (tag === 's' || tag === 'c') {
      const path = tag === 's' ? p[1] : p[2]
      const wm = (tag === 's' ? p[2] : p[3]) ?? 1
      const hand: Hand = (tag === 's' ? p[3] : p[4]) ?? {}
      const colour: ArtColour | 'current' = tag === 's' ? inkKey : p[1]
      const washStroke = colour.endsWith('~')
      const key = (colour === 'acc' ? accent : washStroke ? colour.slice(0, -1) : colour) as PaintKey
      if (colour === 'acc' && tone === 'ui') return
      parsePath(path, { step: Math.max(0.35, 0.9 / k), rnd: pr }).forEach((sub: Sub, j) => {
        if (sub.pts.length < 2) return
        const r = pr.fork('s' + j)
        const px = off(wander(turn(sub.pts), r.fork('w'), k, amp))
        if (tag === 's' || o.silAll) {
          sil.lines.push(openPath(px))
          for (let q = 0; q < px.length; q += 3) sil.pts.push(px[q])
        }
        const pts = roundCorners(px, sub.anchor, cornerR)
        const brush = tag === 'c'
        const w = (nib * wm * (brush ? 1.5 : 1)) / penW
        ink.stroke(pts, sPen, {
          poly: true,
          color: key,
          width: w,
          alpha: washStroke ? 0.5 : brush ? 0.95 : 1,
          wobble: wob,
          speed: 1,
          dry: 0,
          simple: o.crisp,
          start: hand.start ?? 'soft',
          end: hand.end ?? 'soft',
          press: hand.taper ? (t: number) => Math.max(0.3, 1 + hand.taper! * (0.5 - t) * 1.5) : undefined,
        })
      })
    } else if (tag === 'd') {
      const rr = Math.max((p[3] ?? 1.4) * k, nib * 0.62)
      const [tx, ty] = turn([[p[1], p[2]]])[0]
      const x = tx * k + origin[0], y = ty * k + origin[1]
      sil.lines.push(openPath([[x, y], [x + 0.01, y]]))
      sil.pts.push([x, y])
      ink.dot(x, y, rr, sPen, { color: inkKey })
    } else if (tag === 't') {
      const [, text, x, y, em, colour, font] = p
      const px = em * k
      const key = (colour ? (colour === 'acc' ? accent : colour.endsWith('~') ? colour.slice(0, -1) : colour) : inkKey) as PaintKey
      const t = textPath(text, x * k + origin[0], y * k + origin[1], px, pr.fork('t'), { font: font ?? 'hand', jitter: 0 })
      ink.flat('text', t.d, key, 1, { bbox: t.bbox })
      const cap = capHeight(font ?? 'hand', px)
      sil.lines.push(openPath([[t.bbox[0], y * k + origin[1] - cap * 0.5], [t.bbox[2], y * k + origin[1] - cap * 0.5]]))
      sil.pts.push([t.bbox[0], t.bbox[1]], [t.bbox[2], t.bbox[3]])
    }
  })

  return { silhouette: sil, variant, kind, nib, k, w: gw * k, h: gh * k }
}

function smoothPath(px: Pt[]): string {
  return smoothClosed(px, TIERS.lo)
}

export function drawSkeleton(def: ArtDef, size: number, seed: string | number, o: DrawOpts = {}): SkeletonResult {
  const kind = o.kind ?? kindOfDef(def)
  const tier: Tier = o.tier ?? (size >= 128 && (kind === 'doodle' || kind === 'mascot') ? 'hi' : 'lo')
  const ink = new Ink(`${seed}`, { tier, grain: o.grain, calm: o.calm, knobs: o.knobs })
  const r = paintSkeleton(ink, def, size, { ...o, kind })
  const res = ink.toSvg({ w: r.w, h: r.h, pad: o.pad })
  return { ...res, variant: r.variant, kind, nib: r.nib, k: r.k, silhouette: r.silhouette }
}

export interface DieCutOpts extends DrawOpts {
  border?: number
  peel?: boolean | number
  shadow?: boolean
  idPrefix?: string
}

export interface DieCutResult extends SkeletonResult {
  off: number
  border: number
}

export function dieCut(def: ArtDef, size: number, seed: string | number, o: DieCutOpts = {}): DieCutResult {
  const kind = o.kind ?? 'sticker'
  const border = o.border ?? clamp(size * 0.075, 3.5, 8)
  const off = Math.ceil(border + 2)
  const [gw, gh] = def.grid === 24 || def.grid === 64 ? [def.grid, def.grid] : def.grid
  const k = size / Math.max(gw, gh)
  const W = gw * k + 2 * off, H = gh * k + 2 * off
  const tier: Tier = o.tier ?? (size >= 96 ? 'hi' : 'lo')
  const ink = new Ink(`die:${seed}`, { tier, grain: o.grain, calm: o.calm, knobs: o.knobs })
  const id = o.idPrefix ?? `ll-sil-${hashSeed(`${seed}:${size}:${def.parts.length}:${W}`).toString(36)}`
  const art = paintSkeleton(ink, def, size, { silAll: true, ...o, kind, tone: o.tone ?? 'doodle', nib: o.nib ?? clamp(size * (def.nibK ?? 0.055), 1.8, 4.6) }, [off, off])
  const S = art.silhouette
  const bw = 2 * border
  const defs = `<defs><g id="${id}f">${S.fills.map((d) => `<path d="${d}"/>`).join('')}</g><g id="${id}l">${S.lines.map((d) => `<path d="${d}" fill="none"/>`).join('')}</g></defs>`
  const layer = (fill: string, stroke: string, extra: number, op: number, dx = 0, dy = 0): string => {
    const t = dx || dy ? ` transform="translate(${n(dx)} ${n(dy)})"` : ''
    const opa = op < 1 ? ` opacity="${n(op, 100)}"` : ''
    return (
      `<g${t}${opa}><use href="#${id}f" fill="${fill}" stroke="${stroke}" stroke-width="${n(bw + extra)}" stroke-linejoin="round"/>` +
      `<use href="#${id}l" stroke="${stroke}" stroke-width="${n(bw + extra + S.W)}" stroke-linejoin="round" stroke-linecap="round"/></g>`
    )
  }
  let under = defs
  if (o.shadow) under += layer('var(--ll-ink)', 'var(--ll-ink)', 1, 0.1, 0.4, 3.4) + layer('var(--ll-ink)', 'var(--ll-ink)', 0.4, 0.2, 0.2, 1.1)
  under += layer('var(--ll-pencil-mark)', 'var(--ll-pencil-mark)', 1.3, 0.55)
  under += layer('var(--ll-photo)', 'var(--ll-photo)', 0, 1)
  ink.raw(under, 'under')
  ink.grow([0, 0, W, H])
  let res = ink.toSvg({ w: W, h: H, pad: o.pad ?? 2 })
  if (o.peel) res = { ...res, svg: peelCorner(res.svg, S, id, off, border, W, H, o.peel === true ? clamp(size * 0.2, 12, 26) : o.peel, `${seed}`) }
  return { ...res, variant: art.variant, kind, nib: art.nib, k: art.k, silhouette: S, off, border }
}

function peelCorner(svg: string, S: Silhouette, id: string, _off: number, border: number, W: number, H: number, s: number, seed: string): string {
  const R = Math.SQRT1_2
  const d = (p: Pt): number => (p[0] + p[1]) * R
  let dmax = -Infinity
  let tip: Pt = [W, H]
  for (const p of S.pts) {
    if (d(p) > dmax) {
      dmax = d(p)
      tip = p
    }
  }
  dmax += border + 1
  const fold = dmax - s
  const big = 4000
  const at = (dd: number, tt: number): Pt => [(dd + tt) * R, (dd - tt) * R]
  const half = (dd0: number, dd1: number): string => {
    const a = at(dd0, -big), b = at(dd0, big), c = at(dd1, big), e = at(dd1, -big)
    return `M${n(a[0])} ${n(a[1])}L${n(b[0])} ${n(b[1])}L${n(c[0])} ${n(c[1])}L${n(e[0])} ${n(e[1])}Z`
  }
  const tag = hashSeed(`peel:${seed}`).toString(36)
  const keep = `${id}k${tag}`, cut = `${id}r${tag}`, grad = `${id}g${tag}`
  const tt = (tip[0] - tip[1]) * R
  const edge = at(fold, tt)
  const far = at(fold + s * 0.95, tt)
  const m = Math.SQRT2 * fold
  const flap =
    `<g transform="matrix(0 -1 -1 0 ${n(m)} ${n(m)})"><g clip-path="url(#${cut})">` +
    `<use href="#${id}f" fill="url(#${grad})" stroke="url(#${grad})" stroke-width="${n(2 * border)}" stroke-linejoin="round"/>` +
    `<use href="#${id}l" stroke="url(#${grad})" stroke-width="${n(2 * border + S.W)}" stroke-linejoin="round" stroke-linecap="round"/></g></g>`
  const crease = `<path d="M${n(at(fold, tt - s * 1.6)[0])} ${n(at(fold, tt - s * 1.6)[1])}L${n(at(fold, tt + s * 1.6)[0])} ${n(at(fold, tt + s * 1.6)[1])}" stroke="var(--ll-pencil-mark)" stroke-opacity=".35" stroke-width=".8" stroke-linecap="round"/>`
  const defs =
    `<defs><clipPath id="${keep}"><path d="${half(-big, fold)}"/></clipPath><clipPath id="${cut}"><path d="${half(fold, big)}"/></clipPath>` +
    `<linearGradient id="${grad}" gradientUnits="userSpaceOnUse" x1="${n(edge[0])}" y1="${n(edge[1])}" x2="${n(far[0])}" y2="${n(far[1])}">` +
    `<stop offset="0" stop-color="var(--ll-pencil-mark)" stop-opacity=".55"/><stop offset=".3" stop-color="var(--ll-paper)"/><stop offset="1" stop-color="var(--ll-photo)"/></linearGradient></defs>`
  return `${defs}<g clip-path="url(#${keep})">${svg}</g>${flap}${crease}`
}

export function renderSticker(def: StickerDef, size: number, seed: string | number, o: DieCutOpts = {}): DieCutResult | InkResult {
  if (isGen(def)) {
    if (def.gen === 'badge') return dieCut(badgeSkeleton(def.text, def), size, seed, o)
    return stamp(def.text, def.shape, { ...def, seed })
  }
  return dieCut(def, size, seed, o)
}

const CACHE = new Map<string, unknown>()

export function memo<T>(key: string, make: () => T, max = 400): T {
  const hit = CACHE.get(key)
  if (hit !== undefined) {
    CACHE.delete(key)
    CACHE.set(key, hit)
    return hit as T
  }
  const v = make()
  CACHE.set(key, v)
  if (CACHE.size > max) CACHE.delete(CACHE.keys().next().value as string)
  return v
}

