        },
        'top',
      )
    })

    if (interactive) {
      ink.layer('hover', () => {
        if (calm) return
        const d = 3.6
        ink.lines(
          [{ pts: chain([[r + d + 2, h + d], [w + d, h + d], [w + d, r + d + 2]], [0, 0], Math.max(2.5, r), ink.next('drop')), o: RULER }],
          'ink.fine',
          { width: 1.35 },
        )
      })
    }
  },
})

