const CodeBlock = defineUi<CodeBlockProps>("CodeBlock", ["code", "language", "filename", "lineNumbers", "diff", "wrap", "startLine", "copyable", "stock", "tape", "tone", "seed", "class"], (_props, {
  slots: _slots
