export const fieldChoiceRecipe = defineRecipe<Record<string, never>>({
  id: 'field-choice',
  kind: 'card',
  layers: ['rest', 'hover', 'checked'],
  pad: 12,
  draw(ink, { w, h }, _p, ctx) {
    const r = clamp(Math.min(w, h) * 0.06, 2, 4)
    const body = roundRectPoly(1.5, 1.5, w - 3, h - 3, r)
