  paused: boolean
}

export const marqueeControlRecipe = defineRecipe<MarqueeControlParams>({
  id: 'marquee-control',
  kind: 'marquee-control',
  layers: ['rest', 'hover', 'focus'],
  lazy: ['focus'],
  pad: 12,
