      } else {
        ink.lines([{ pts: [[cx - k * 0.55, cy - k], [cx - k * 0.5, cy + k]], o: { start: 'soft', end: 'soft' } }, { pts: [[cx + k * 0.55, cy - k], [cx + k * 0.6, cy + k]], o: { start: 'soft', end: 'soft' } }], 'ink', { width: 1.1 })
      }
    })
    ink.layer('hover', () => {
      loop(ink, cx, cy, r + 2.2, r + 2, { pen: 'ink.fine', turns: 1.05 })
    })
  },
})

