    kind: "peel-corner-flap" as const,
    size: [size.value, size.value],
    seed: seed.value
  }));
  const flap = computed(() => proxyRefs(_flapCore));
  const _hitCore = useInk(() => ({
    recipe: peelTriggerRecipe,
    params: {},
    kind: "peel-corner-trigger" as const,
