    if (peeledProp.value === undefined) setInner(v);
    onPeeledChange.value?.(v);
    tween.value(v ? OPEN : REST);
    if (peeledProp.value !== undefined) {
      clearTimeout(decline.value);
      decline.value = setTimeout(() => {
