  pen(ink, [[x + ww * 0.56, y + hh * 0.26], [x + ww * 0.82, y + hh * 0.26], [x + ww * 0.82, y + hh * 0.26 + ww * 0.24], [x + ww * 0.56, y + hh * 0.26 + ww * 0.24], [x + ww * 0.56, y + hh * 0.26]], 'ink', { poly: true, width: 0.9 })
