  const swap = (s: string) => s.replaceAll('var(--ll-ink)', 'currentColor')
  return { ...res, svg: swap(res.svg), parts: Object.fromEntries(Object.entries(res.parts).map(([k, v]) => [k, swap(v ?? '')])) }
