        for (let k = i ? 1 : 0; k <= 8; k++) {
          const t = k / 8
          pts.push([a + (b - a) * t + rng.gauss(0, 0.15), y + amp * 1.0 - Math.sin(Math.PI * t) * amp * 2.1 * rng.range(0.92, 1.06)])
