      }
      pull(pts)
    } else if (p.kind === 'dashes') {
      let x = x0 + rng.range(0, 4)
      while (x < x1 - 4) {
        const len = rng.range(6, 11)
        lines.push({ pts: [[x, y + rng.gauss(0, 0.5)], [Math.min(x1, x + len), y + rng.gauss(0, 0.6)]], o: { start: 'soft', end: 'soft', wobble: 0.4, simple: true } })
