      const draw = () => {
        if (p.animate) revealMark(ink, { id: markRevealId(ctx.seed, 's'), lines, pen, box: { w: L, h: T }, pad: 10, width, opts: { dry: STRUCTURAL_DRY }, revealWidth: Math.max(6, T * 0.8) })
