  const t = tableTiles();
  return sheet = `@layer components {
:root { --ll-tbl-rule: ${t.rule}; --ll-tbl-head: ${t.head}; --ll-tbl-cap-a: ${t.capStart}; --ll-tbl-cap-b: ${t.capEnd}; }
[data-slot="table"] {
