[data-slot="table-row"] > :is(td, th):last-child::after { mask-image: var(--ll-tbl-img), var(--ll-fade-e); }
[data-slot="table-row"] > :is(td, th):only-child::after { mask-image: var(--ll-tbl-img), var(--ll-fade-se); }
