    shared: ["email", "app"],
    news: []
  },
  quiet: {
    on: true,
    from: "22:00" as const,
    to: "07:30" as const,
    days: ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
  },
  summary: {
    day: "fri" as const,
    tally: true
  }
};
export const TIMES: {
  value: string;
  label: string;
}[] = Array.from({
  length: 48
}, (_, i) => {
  const h = Math.floor(i / 2);
