                          </SidebarMenuButton>
                        </SidebarMenuItem>;
                  })}
                  </SidebarMenu>
                </SidebarGroupContent>
              </CollapsibleContent>
            </Collapsible>
          </SidebarGroup>
          <SidebarSeparator class="mx-0" />
        </Fragment>)}
    </>;
  };
});

